(function () {
const L = (en, ja, zh) => ({ en, ja, zh });

// Simplified climatograph (biome distribution against temperature and rainfall). Illustrative boundaries.
function climatograph(lang) {
  const T = {
    x: { en: "Mean annual temperature (°C)", ja: "年平均気温 (°C)", zh: "年平均氣溫 (°C)" },
    y: { en: "Annual rainfall (mm)", ja: "年降水量 (mm)", zh: "年降雨量 (mm)" },
    cap: { en: "Simplified biome map (illustrative boundaries). Real biomes overlap and change gradually. Tropical forest continues above 4000 mm.", ja: "バイオームの簡略図（境界は説明用）。実際のバイオームは重なり、徐々に移り変わります。熱帯林は4000 mmを超える範囲にも続きます。", zh: "簡化的生物群系圖（界線只作示意）。實際的生物群系會重疊並逐漸過渡。熱帶森林在4000 mm以上仍繼續。" },
    tun: ["Tundra", "ツンドラ", "苔原", "tundra"],
    tai: ["Taiga", "タイガ", "針葉林", "taiga"],
    gra: ["Grassland", "草原", "草原", "grassland"],
    tem: ["Temperate forest", "温帯林", "溫帶森林", "temperate forest"],
    des: ["Hot desert", "熱帯砂漠", "熱帶沙漠", "hot desert"],
    tro: ["Tropical forest", "熱帯林", "熱帶森林", "tropical forest"]
  };
  const lg = { en: 0, ja: 1, zh: 2 }[lang];
  const cap = T.cap[lang] || T.cap.en;
  // plot area: x 60..340 (temp -15..30), y 20..210 (rain 4000..0)
  const X = (c) => 60 + (c + 15) / 45 * 280;
  const Y = (r) => 210 - Math.min(r, 4000) / 4000 * 190;
  const box = (c1, c2, r1, r2, fill) => `<rect x="${X(c1).toFixed(1)}" y="${Y(r2).toFixed(1)}" width="${(X(c2) - X(c1)).toFixed(1)}" height="${(Y(r1) - Y(r2)).toFixed(1)}" fill="${fill}"/>`;
  // label: one line (name + english in brackets) or two lines
  const label = (k, c1, c2, r1, r2, two) => {
    const arr = T[k], cx = (X(c1) + X(c2)) / 2, cy = (Y(r1) + Y(r2)) / 2;
    const en = arr[0];
    if (lang === "en") return `<text x="${cx.toFixed(1)}" y="${(cy + 3).toFixed(1)}">${en}</text>`;
    if (two) return `<text x="${cx.toFixed(1)}" y="${(cy - 1).toFixed(1)}">${arr[lg]}</text><text x="${cx.toFixed(1)}" y="${(cy + 8).toFixed(1)}" font-size="6.5">(${arr[3]})</text>`;
    return `<text x="${cx.toFixed(1)}" y="${(cy + 2.5).toFixed(1)}" font-size="7.5">${arr[lg]} (${arr[3]})</text>`;
  };
  return `<figure><svg viewBox="0 0 360 270" width="100%" role="img" aria-label="${cap}" style="max-width:520px;font-family:var(--font-body,sans-serif)">
  <rect x="60" y="20" width="280" height="190" fill="var(--surface-2,#e3eaee)" stroke="var(--line,#c3d0d7)"/>
  <g stroke="var(--ink,#0f2029)" stroke-width="0.8" fill-opacity="0.55">
   ${box(-15, -3, 0, 500, "var(--theme-a,#07756f)")}
   ${box(-10, 5, 500, 1000, "var(--lvl-3,#4a7a2a)")}
   ${box(0, 28, 250, 750, "var(--warn,#c98a00)")}
   ${box(5, 20, 1000, 2500, "var(--good,#2a9d5c)")}
   ${box(15, 30, 0, 250, "var(--bad,#d1495b)")}
   ${box(20, 30, 2000, 4000, "var(--accent,#2547c7)")}
  </g>
  <g font-size="8.5" fill="var(--ink,#0f2029)" text-anchor="middle" style="fill:var(--ink,#0f2029)">
   ${label("tun", -15, -3, 0, 500, true)}
   ${label("tai", -10, 5, 500, 1000, true)}
   ${label("gra", 5, 28, 250, 750, false)}
   ${label("tem", 5, 20, 1000, 2500, true)}
   ${label("des", 15, 30, 0, 250, false)}
   ${label("tro", 20, 30, 2000, 4000, true)}
  </g>
  <g font-size="8" fill="var(--muted,#4d626d)" text-anchor="middle" style="fill:var(--muted,#4d626d)">
   ${[-15, -10, -5, 0, 5, 10, 15, 20, 25, 30].map(c => `<text x="${X(c)}" y="222">${c}</text>`).join('')}
   ${[0, 1000, 2000, 3000, 4000].map(r => `<text x="54" y="${Y(r) + 3}" text-anchor="end">${r}</text>`).join('')}
  </g>
  <text x="200" y="244" font-size="10" text-anchor="middle" style="fill:var(--ink,#0f2029)">${T.x[lang] || T.x.en}</text>
  <text transform="translate(12 115) rotate(-90)" font-size="10" text-anchor="middle" style="fill:var(--ink,#0f2029)">${T.y[lang] || T.y.en}</text>
 </svg><figcaption>${cap}</figcaption></figure>`;
}
const CL = { en: climatograph("en"), ja: climatograph("ja"), zh: climatograph("zh") };

IB.registerTopic({
  id: "B4.1",
  slug: "b4-1",
  theme: "B",
  level: 4,
  ahlOnly: false,
  title: L("Adaptation to environment", "環境への適応", "對環境的適應"),
  guidingQuestions: [
    L("How are the adaptations and habitats of species related?", "種の適応と生息地はどのように関係しているか。", "物種的適應與生境有甚麼關係？"),
    L("What causes the similarities between ecosystems within a terrestrial biome?", "陸上のバイオーム内の生態系が似ているのはなぜか。", "同一陸地生物群系內的生態系統為何相似？")
  ],
  summary: L(
    "Every species lives in a habitat and has adaptations that suit the abiotic (non-living) conditions there. Each species can tolerate only a certain range of each factor, and that range helps to decide where it is found. On a global scale, temperature and rainfall decide which biome develops, and similar biomes have similar-looking organisms because of convergent evolution.",
    "どの種も生息地に住み、そこの非生物的条件に合った適応をもっています。種は各要因のある範囲しか耐えられず、その範囲が分布を決める一因です。地球規模では、気温と降水量がどのバイオームが成立するかを決め、収れん進化のため似たバイオームには似た姿の生物が見られます。",
    "每個物種都生活在某生境，並具有適合當地非生物環境的適應特徵。物種只能耐受每個因素的某個範圍，這範圍有助決定它在哪裏出現。在全球尺度上，氣溫和雨量決定會形成哪種生物群系，而由於趨同演化，相似的生物群系有外貌相似的生物。"
  ),
  sections: [
    {
      ref: "B4.1.1", ahl: false,
      deeperTitle: L("Habitat or niche? Describing precisely", "生息場所とニッチ: 正確に述べる", "棲息地還是生態位？準確描述"),
      deeper: L("<p><strong>Three layers of a good habitat description.</strong> Move from large to small: region, then physical position, then ecosystem type. For marram grass: <em>the coast of north-west Europe (geographical) – the front dunes just above the high-tide line (physical) – a sand-dune ecosystem.</em></p><table><tr><th>Question</th><th>Concept</th><th>Example: mangrove tree</th></tr><tr><td>Where does it live?</td><td>Habitat</td><td>Muddy, salty tidal shores of tropical coasts (a mangrove swamp)</td></tr><tr><td>What does it do and what does it need?</td><td>Niche (see B4.2)</td><td>Producer; tolerates salt and waterlogging; its roots shelter young fish</td></tr></table><ul><li>A habitat can be described for a whole <strong>community</strong>, one <strong>species</strong>, a <strong>population</strong> or a single <strong>individual</strong>. A rocky shore is the habitat of the shore community, but the habitat of one limpet is a patch of rock on the mid shore.</li><li>One habitat holds many species, each with a different niche.</li></ul><div class=\"note\"><strong>Mark-scheme language:</strong> \"the place where an organism lives\" earns the mark for habitat. \"Its role in the ecosystem\" is niche and does not.</div>", "<p><strong>よい生息場所の記述の3層。</strong>大きいものから小さいものへ、地域、物理的な位置、生態系の種類の順に述べます。マラムグラス (marram grass)の例: <em>北西ヨーロッパの海岸（地理的）－満潮線のすぐ上の前面砂丘（物理的）－砂丘の生態系。</em></p><table><tr><th>問い</th><th>概念</th><th>例: マングローブの木</th></tr><tr><td>どこに住むか</td><td>生息場所 (habitat)</td><td>熱帯の海岸の、泥が多く塩分のある潮間帯（マングローブ湿地）</td></tr><tr><td>何をし、何を必要とするか</td><td>ニッチ (niche)（B4.2参照）</td><td>生産者。塩分と水浸しに耐える。根は幼魚の隠れ場所になる</td></tr></table><ul><li>生息場所は、<strong>群集 (community)</strong>全体、1つの<strong>種 (species)</strong>、<strong>個体群 (population)</strong>、1個体のいずれについても述べられます。岩礁海岸は海岸群集の生息場所ですが、1匹のカサガイの生息場所は中潮帯の岩の一角です。</li><li>1つの生息場所には多くの種がおり、それぞれ異なるニッチをもちます。</li></ul><div class=\"note\"><strong>採点基準の表現:</strong>「生物が住む場所」は生息場所の得点になります。「生態系での役割」はニッチであり、得点になりません。</div>", "<p><strong>良好的棲息地描述有三個層次。</strong>由大至小：地區、物理位置、生態系統類型。以濱草 (marram grass) 為例：<em>歐洲西北部海岸（地理位置）－高潮線上方的前沿沙丘（物理位置）－沙丘生態系統。</em></p><table><tr><th>問題</th><th>概念</th><th>例子：紅樹</th></tr><tr><td>它住在哪裏？</td><td>棲息地 (habitat)</td><td>熱帶海岸泥濘而含鹽的潮間帶（紅樹林沼澤）</td></tr><tr><td>它做甚麼、需要甚麼？</td><td>生態位 (niche)（見B4.2）</td><td>生產者；耐鹽及耐水浸；根部為幼魚提供庇護</td></tr></table><ul><li>棲息地可以針對整個<strong>群落 (community)</strong>、一個<strong>物種 (species)</strong>、一個<strong>種群 (population)</strong>或單一<strong>個體</strong>來描述。岩岸是岸邊群落的棲息地，而一隻笠螺的棲息地則是中潮帶的一小塊岩石。</li><li>一個棲息地容納許多物種，各有不同的生態位。</li></ul><div class=\"note\"><strong>評分準則用語：</strong>「生物居住的地方」可得棲息地的分數；「在生態系統中的角色」是生態位，不能得分。</div>"),
      heading: L("Habitat", "生息地", "生境 (habitat)"),
      body: L(
        "<p>A <strong>habitat</strong> is the place where a community, species, population or individual organism lives. A good description of a habitat can include:</p><ul><li>the <strong>geographical location</strong> (for example, the east coast of Scotland);</li><li>the <strong>physical location</strong> (for example, the upper layer of a rocky shore, or the soil under leaf litter);</li><li>the <strong>type of ecosystem</strong> (for example, sand dune, mangrove swamp or tropical rainforest).</li></ul><p>Do not mix up habitat with niche. The habitat is where an organism lives (its address). The niche is its role in the ecosystem (its job); see B4.2.</p>",
        "<p><strong>生息地 (habitat)</strong> とは、群集、種、個体群、または個体が生活する場所です。生息地の説明には次のものを含めることができます。</p><ul><li><strong>地理的な位置</strong>（例: スコットランドの東海岸）</li><li><strong>物理的な位置</strong>（例: 岩礁海岸の上部、落ち葉の下の土壌）</li><li><strong>生態系の種類</strong>（例: 砂丘、マングローブ湿地、熱帯雨林）</li></ul><p>生息地とニッチ (niche) を混同しないこと。生息地は生物が住む場所（住所）で、ニッチは生態系での役割（仕事）です。B4.2を参照してください。</p>",
        "<p><strong>生境 (habitat)</strong> 是群落、物種、種群或個別生物生活的地方。描述生境時可包括：</p><ul><li><strong>地理位置</strong>（例如蘇格蘭東岸）；</li><li><strong>物理位置</strong>（例如岩岸的上層，或落葉層下的土壤）；</li><li><strong>生態系統類型</strong>（例如沙丘、紅樹林沼澤或熱帶雨林）。</li></ul><p>不要混淆生境與生態位 (niche)。生境是生物居住的地方（地址），生態位是它在生態系統中的角色（工作），見B4.2。</p>"
      )
    },
    {
      ref: "B4.1.2", ahl: false,
      deeperTitle: L("Adaptations step by step: problem, feature, mechanism", "適応を順に考える: 問題・特徴・仕組み", "逐步分析適應：難題、特徵、機制"),
      deeper: L("<p>Good answers link three things. The table shows the reasoning.</p><table><tr><th>Abiotic problem</th><th>Feature</th><th>Mechanism (why it works)</th></tr><tr><td>Dry sand, wind: water loss</td><td>Rolled leaf, stomata inside, hairs</td><td>Water vapour collects inside the roll, so the concentration gradient between leaf and air is smaller and less water diffuses out. Hairs trap still, humid air.</td></tr><tr><td>Water drains away quickly</td><td>Long roots and rhizomes</td><td>Reach water deeper in the sand; the spreading network also anchors the shifting sand.</td></tr><tr><td>Burial by blown sand</td><td>Regrows upwards</td><td>Shoots keep reaching the light; the plant builds up the dune as it grows.</td></tr><tr><td>Little oxygen in waterlogged mud</td><td>Roots above the mud</td><td>Air-exposed roots with pores let oxygen diffuse in for respiration.</td></tr><tr><td>Salt water around roots</td><td>Excluding salt at the roots, or secreting it from leaves</td><td>Seawater is very salty; if too much salt enters, the tree could not take up water by osmosis or would be poisoned.</td></tr><tr><td>Soft mud, tidal water</td><td>Prop roots; viviparous seedlings (<em>Rhizophora</em>)</td><td>Roots spread the weight. A large seedling that is already growing drops and roots at once instead of being washed away as a tiny seed.</td></tr></table><div class=\"note\"><strong>Mark-scheme language:</strong> \"reduces water loss\" alone is weak. Say \"reduces transpiration <em>because</em> humid air trapped inside the rolled leaf lowers the water-vapour gradient\". Name the species when asked for an example.</div>", "<p>よい答えは3つを結びつけます。表で考え方を示します。</p><table><tr><th>非生物的な問題</th><th>特徴</th><th>仕組み（なぜ効くか）</th></tr><tr><td>乾いた砂と風: 水分の損失</td><td>巻いた葉、内側の気孔、毛</td><td>水蒸気が巻いた葉の中にたまり、葉と空気の間の濃度勾配が小さくなって、拡散で出る水が減る。毛は動かない湿った空気をとどめる。</td></tr><tr><td>水がすぐ流れ去る</td><td>長い根と地下茎 (rhizome)</td><td>砂の深くにある水に届く。広がった根のネットワークは動く砂も固定する。</td></tr><tr><td>風で運ばれた砂に埋もれる</td><td>上方へ再び伸びる</td><td>芽が光に届き続ける。成長しながら砂丘を高くする。</td></tr><tr><td>水浸しの泥は酸素が少ない</td><td>泥の上に出た根</td><td>空気に触れる根には小さな孔があり、呼吸用の酸素が拡散で入る。</td></tr><tr><td>根のまわりが塩水</td><td>根で塩を排除する、または葉から塩を分泌する</td><td>海水は塩分が非常に高い。塩が入りすぎると浸透で水を吸えなくなったり、毒になったりする。</td></tr><tr><td>やわらかい泥と潮の水</td><td>支柱根、胎生の種子（<em>Rhizophora</em>）</td><td>根が重さを分散する。すでに成長した大きな芽生えが落ちてすぐ根づくので、小さな種子のように流されない。</td></tr></table><div class=\"note\"><strong>採点基準の表現:</strong>「水分の損失を減らす」だけでは弱い答えです。「巻いた葉の内側にたまった湿った空気が水蒸気の勾配を小さくするので蒸散が減る」と<em>理由</em>を述べます。例を求められたら種名を書きます。</div>", "<p>好的答案會連繫三件事。下表示範推理。</p><table><tr><th>非生物難題</th><th>特徵</th><th>機制（為何有效）</th></tr><tr><td>沙乾風大：失水</td><td>葉捲起、氣孔在內側、有毛</td><td>水蒸氣積聚在捲葉內，葉與空氣之間的濃度梯度變小，擴散流失的水較少；毛困住靜止濕潤的空氣。</td></tr><tr><td>水很快流走</td><td>長根和根狀莖 (rhizome)</td><td>能到達沙中較深處的水；散開的根系也固定流動的沙。</td></tr><tr><td>被風吹來的沙掩埋</td><td>向上重新生長</td><td>芽持續伸向光；生長時也令沙丘增高。</td></tr><tr><td>水浸泥土缺氧</td><td>露出泥面的根</td><td>暴露於空氣的根有小孔，氧氣可擴散進入供呼吸。</td></tr><tr><td>根周圍是鹹水</td><td>在根部排除鹽分，或由葉分泌鹽分</td><td>海水含鹽量很高；鹽分進入過多，樹木無法以滲透作用吸水，甚至中毒。</td></tr><tr><td>軟泥和潮水</td><td>支柱根；胎生幼苗（<em>Rhizophora</em>）</td><td>根分散重量；已長大的幼苗掉下即可扎根，不像細小種子容易被沖走。</td></tr></table><div class=\"note\"><strong>評分準則用語：</strong>只寫「減少失水」不夠好。要寫「捲葉內積聚的濕潤空氣降低水蒸氣梯度，所以蒸騰減少」，說明<em>原因</em>。題目要求例子時須寫出物種名稱。</div>"),
      heading: L("Adaptations to the abiotic environment: dune grass and mangrove", "非生物的環境への適応: 砂丘の草とマングローブ", "對非生物環境的適應：沙丘草與紅樹"),
      body: L(
        "<p>An <strong>adaptation</strong> is an inherited feature that helps an organism survive and reproduce in its habitat. <strong>Abiotic</strong> means non-living (for example water, temperature, salt, light). The guide asks for a grass of sand dunes and a tree of mangrove swamps.</p><p><strong>Marram grass</strong> (<em>Ammophila arenaria</em>) on sand dunes. Dunes are dry (water drains quickly through sand), windy, salty and unstable.</p><ul><li>Leaves roll up, with stomata inside the rolled leaf, and have hairs. This traps humid air and reduces water loss by transpiration.</li><li>Long, spreading roots and underground stems (rhizomes) reach water deep in the sand and hold the sand in place.</li><li>It can regrow upwards when covered by blown sand.</li></ul><p><strong>Mangrove trees</strong> such as <em>Rhizophora</em> (red mangrove) or <em>Avicennia</em> (black mangrove). Mangrove mud is salty, waterlogged and has little oxygen.</p><ul><li>Roots that grow above the mud (prop roots or breathing roots) allow gas exchange in oxygen-poor mud.</li><li>Salt is excluded at the roots or secreted from the leaves, so the tree can use salt water.</li><li>Prop roots give support in soft mud.</li><li>In <em>Rhizophora</em>, seeds germinate while still on the tree. The large seedlings drop into the mud and quickly root.</li></ul>",
        "<p><strong>適応 (adaptation)</strong> とは、生息地で生存・繁殖するのに役立つ遺伝する特徴です。<strong>非生物的 (abiotic)</strong> とは水、温度、塩分、光など生きていないものを指します。指針は砂丘の草とマングローブ湿地の樹木を求めています。</p><p>砂丘の<strong>マラムグラス (marram grass、<em>Ammophila arenaria</em>)</strong>。砂丘は乾燥し（水は砂をすぐに通り抜ける）、風が強く、塩分があり、不安定です。</p><ul><li>葉が巻いて気孔が巻いた葉の内側にあり、毛もあります。湿った空気をためて蒸散による水分の損失を減らします。</li><li>長く広がる根と地下茎 (rhizome) が砂の深くの水に届き、砂を固定します。</li><li>風で運ばれた砂に埋まっても上に向かって伸びます。</li></ul><p><strong>マングローブの樹木</strong>（<em>Rhizophora</em>（ヤエヤマヒルギ類）や<em>Avicennia</em>（ヒルギダマシ類）など）。マングローブの泥は塩分が高く、水浸しで酸素が乏しい環境です。</p><ul><li>泥の上に出る根（支柱根や呼吸根）が、酸素の乏しい泥の中でのガス交換を可能にします。</li><li>根で塩分を排除するか葉から排出し、塩水を利用できます。</li><li>支柱根が柔らかい泥の中で体を支えます。</li><li><em>Rhizophora</em>では、種子が樹上にいる間に発芽します。大きな芽生えが泥に落ちて素早く根づきます。</li></ul>",
        "<p><strong>適應 (adaptation)</strong> 是有助生物在其生境中生存和繁殖的遺傳特徵。<strong>非生物 (abiotic)</strong> 指沒有生命的因素，例如水、溫度、鹽分、光。指引要求以沙丘的一種草和紅樹林沼澤的一種樹為例。</p><p>沙丘上的<strong>濱草 (marram grass，<em>Ammophila arenaria</em>)</strong>。沙丘乾燥（水很快滲過沙）、多風、含鹽且不穩定。</p><ul><li>葉片捲起，氣孔位於捲起的葉內，並有毛。這樣能困住濕潤空氣，減少蒸騰失水。</li><li>長而廣闊的根和地下莖 (rhizome) 可到達沙內深處的水分，並固定沙粒。</li><li>被風吹來的沙覆蓋後，仍能向上生長。</li></ul><p><strong>紅樹</strong>，例如<em>Rhizophora</em>（紅樹屬）或<em>Avicennia</em>（海欖雌屬）。紅樹林的泥土含鹽、積水且缺氧。</p><ul><li>長出泥面的根（支持根或呼吸根）讓樹在缺氧的泥中進行氣體交換。</li><li>在根部排除鹽分，或由葉片排出鹽分，令樹木能利用鹹水。</li><li>支持根在軟泥中支撐樹身。</li><li><em>Rhizophora</em>的種子在母樹上已開始萌發，大型幼苗掉進泥中後迅速生根。</li></ul>"
      ),
      examTip: L("When asked to explain an adaptation, link feature, function and the abiotic problem it solves (e.g. rolled leaf, traps humid air, less transpiration in a dry, windy dune).", "適応を説明するときは、特徴・機能・解決する非生物的問題を結びつけます（例: 巻いた葉が湿った空気をためて、乾燥して風の強い砂丘での蒸散を減らす）。", "解釋適應時，要連繫特徵、功能和所解決的非生物問題（例如捲葉困住濕潤空氣，減少在乾燥多風沙丘的蒸騰）。")
    },
    {
      ref: "B4.1.3", ahl: false,
      deeperTitle: L("Reading a tolerance range: worked example", "耐性の範囲を読む: 例題", "解讀耐受範圍：實例"),
      deeper: L("<p><strong>Worked example.</strong> A shrub survives between -5 °C and 35 °C. It grows best at about 20 °C.</p><table><tr><th>Mean temperature at a site</th><th>Zone</th><th>What to expect</th></tr><tr><td>20 °C</td><td>Optimum</td><td>Healthy, common, reproduces well</td></tr><tr><td>30 °C</td><td>Stress (inside the range, away from the optimum)</td><td>Present but small, few seeds</td></tr><tr><td>38 °C</td><td>Outside the range</td><td>Absent, however good the soil is. Temperature is the limiting factor.</td></tr></table><ul><li><strong>Many factors act together.</strong> A species lives at a site only if <em>every</em> factor is within its range. Good light cannot make up for soil that is too salty.</li><li><strong>Different species, different ranges.</strong> A fish from cold, fast streams needs high dissolved oxygen, but a fish of warm, still ponds tolerates much less. So the two live in different places.</li><li><strong>Tolerance can change with life stage.</strong> Seedlings and larvae often tolerate a narrower range than adults, so the range for the whole life cycle is set by the most sensitive stage.</li></ul><div class=\"note\"><strong>Mark-scheme language:</strong> \"outside its range of tolerance, so it cannot survive there\"; \"near the limit, the organism is stressed and growth or reproduction is poor\"; \"the factor closest to its limit is the limiting factor\".</div>", "<p><strong>例題。</strong>ある低木は-5 °Cから35 °Cの間で生存でき、20 °C付近で最もよく育ちます。</p><table><tr><th>ある地点の平均気温</th><th>領域</th><th>予想される姿</th></tr><tr><td>20 °C</td><td>最適 (optimum)</td><td>健全で個体数が多く、よく繁殖する</td></tr><tr><td>30 °C</td><td>ストレス域（範囲内だが最適から離れる）</td><td>生えるが小さく、種子が少ない</td></tr><tr><td>38 °C</td><td>範囲外</td><td>土壌がどれほどよくても生えない。気温が制限要因 (limiting factor)。</td></tr></table><ul><li><strong>多くの要因が同時に働く。</strong>種がある地点にすむのは、<em>すべて</em>の要因が耐性の範囲内にあるときだけです。光が十分でも、土壌の塩分が高すぎれば補えません。</li><li><strong>種が違えば範囲も違う。</strong>冷たく流れの速い川の魚は溶存酸素が多く必要ですが、温かい止水の池の魚はずっと少なくても耐えます。そのため両者は別の場所にすみます。</li><li><strong>耐性は生活史の段階で変わる。</strong>芽生えや幼生は成体より耐えられる範囲が狭いことが多く、生活環全体の範囲は最も敏感な段階で決まります。</li></ul><div class=\"note\"><strong>採点基準の表現:</strong>「耐性の範囲 (range of tolerance) の外なので、そこでは生存できない」「限界付近では生物はストレスを受け、成長や繁殖が悪い」「限界に最も近い要因が制限要因」。</div>", "<p><strong>實例。</strong>某灌木能在-5 °C至35 °C之間生存，約20 °C時生長最佳。</p><table><tr><th>某地點平均溫度</th><th>區間</th><th>預期情況</th></tr><tr><td>20 °C</td><td>最適 (optimum)</td><td>健康、常見、繁殖良好</td></tr><tr><td>30 °C</td><td>受壓區（在範圍內但遠離最適）</td><td>有出現但細小，種子少</td></tr><tr><td>38 °C</td><td>範圍之外</td><td>不論土壤多好都不會出現。溫度是限制因素 (limiting factor)。</td></tr></table><ul><li><strong>多個因素同時作用。</strong>物種只有在<em>所有</em>因素都在耐受範圍內，才能在某地生存。光線充足也補償不了過鹹的土壤。</li><li><strong>不同物種，範圍不同。</strong>冷而急流溪流中的魚需要高溶解氧，暖而靜止池塘的魚耐受的氧量低得多，所以二者生活在不同地方。</li><li><strong>耐受性會隨生活階段改變。</strong>幼苗和幼蟲往往比成體耐受範圍窄，所以整個生命周期的範圍由最敏感的階段決定。</li></ul><div class=\"note\"><strong>評分準則用語：</strong>「在耐受範圍 (range of tolerance) 之外，所以不能在那裏生存」；「接近極限時生物受壓，生長或繁殖欠佳」；「最接近極限的因素就是限制因素」。</div>"),
      heading: L("Abiotic variables and range of tolerance", "非生物的変数と耐性の範囲", "非生物變量與耐受範圍"),
      body: L(
        "<p>The distribution of a species (where it is found) is affected by <strong>abiotic variables</strong>. The guide asks for examples for both plants and animals.</p><table><tr><th>Plants</th><th>Animals</th></tr><tr><td>Temperature, light intensity, water availability, soil pH, soil salinity, wind</td><td>Temperature, water availability (humidity), oxygen concentration (in water), salinity, pH, light (for example for finding food)</td></tr></table><p>Adaptations give each species a <strong>range of tolerance</strong> for each variable. This is the span of values within which the species can survive. Within the range there is an optimum where it does best. Near the edges it is stressed and survives poorly. Outside the range it cannot survive.</p><p>So the abiotic conditions in a place decide whether a species can live there.</p>",
        "<p>種の分布（どこに見られるか）は<strong>非生物的変数 (abiotic variables)</strong> の影響を受けます。指針は植物と動物の両方の例を求めています。</p><table><tr><th>植物</th><th>動物</th></tr><tr><td>温度、光の強さ、水の利用しやすさ、土壌のpH、土壌の塩分、風</td><td>温度、水の利用しやすさ（湿度）、（水中の）酸素濃度、塩分、pH、光（例: 餌を見つけるため）</td></tr></table><p>適応により、各種はそれぞれの変数に対する<strong>耐性の範囲 (range of tolerance)</strong> をもちます。これは種が生存できる値の幅です。範囲内には最もよく成育する最適値があります。範囲の端ではストレスを受けて生存しにくく、範囲の外では生存できません。</p><p>したがって、ある場所の非生物的条件がそこに種が住めるかどうかを決めます。</p>",
        "<p>物種的分佈（在哪裏出現）受<strong>非生物變量 (abiotic variables)</strong> 影響。指引要求植物和動物各舉例。</p><table><tr><th>植物</th><th>動物</th></tr><tr><td>溫度、光強度、水分供應、土壤pH、土壤鹽度、風</td><td>溫度、水分供應（濕度）、（水中的）氧濃度、鹽度、pH、光（例如用來尋找食物）</td></tr></table><p>適應特徵使每個物種對每個變量有一個<strong>耐受範圍 (range of tolerance)</strong>，即物種能存活的數值範圍。範圍內有最適值，物種在此表現最佳；接近範圍邊緣時受壓力而難以存活；超出範圍則不能存活。</p><p>因此，一個地方的非生物條件決定物種能否在該處生活。</p>"
      )
    },
    {
      ref: "B4.1.4", ahl: false,
      deeperTitle: L("Transect data: numbers, correlation and good method", "トランセクトのデータ: 数値・相関・よい方法", "樣帶數據：數字、相關與良好方法"),
      deeper: L("<p><strong>Line or belt?</strong> In a <em>line transect</em> you record only organisms touching the tape. In a <em>belt transect</em> you place quadrats along the tape, so more data per site but more work. Both show change along a gradient.</p><p><strong>Worked calculation.</strong> Percentage cover in five quadrats along a transect is 60, 45, 25, 10 and 2. Mean cover = (60 + 45 + 25 + 10 + 2) / 5 = 28.4 %. Repeating the transect gives a second set of values to compare.</p><p><strong>Interpreting r and R².</strong> The correlation coefficient <em>r</em> runs from -1 to +1.</p><ul><li>+0.92 (positive): cover rises as light rises. It is a strong, positive correlation.</li><li>-0.88 (negative): cover falls as soil salinity rises.</li><li>Near 0: no linear relationship.</li><li>R² of a trend line (for example 0.85) shows how well the line fits the points. The closer to 1, the better the fit; 0.85 means the line accounts for about 85 % of the variation.</li></ul><p><strong>Making the method reliable:</strong> same quadrat size throughout; measure the abiotic variable in the same quadrats and at the same time; random numbers to avoid bias when choosing positions; repeat the transect at other places, then compare means.</p><div class=\"note\"><strong>Mark-scheme language:</strong> \"correlation does not show causation\"; \"another variable changes along the transect (confounding variable)\"; \"repeat to check the pattern is reliable\". The sign of <em>r</em> tells you direction, its size tells you strength.</div>", "<p><strong>ライン法かベルト法か。</strong><em>ライントランセクト (line transect)</em>では、テープに触れた生物だけを記録します。<em>ベルトトランセクト (belt transect)</em>では、テープに沿って方形枠を置くので、1地点のデータは多くなりますが手間も増えます。どちらも勾配に沿った変化を示します。</p><p><strong>計算例。</strong>トランセクト沿いの5つの方形枠の被度 (percentage cover) が60、45、25、10、2 %のとき、平均被度 = (60 + 45 + 25 + 10 + 2) / 5 = 28.4 %。トランセクトを繰り返せば、比較できる2組目の値が得られます。</p><p><strong>r と R² の読み方。</strong>相関係数 (correlation coefficient) <em>r</em> は-1から+1の値をとります。</p><ul><li>+0.92（正）: 光が強いほど被度が大きい。強い正の相関です。</li><li>-0.88（負）: 土壌の塩分が高いほど被度が小さい。</li><li>0に近い: 直線的な関係がない。</li><li>近似直線のR²（例: 0.85）は直線のあてはまりのよさを示します。1に近いほどよく、0.85なら直線がばらつきの約85 %を説明します。</li></ul><p><strong>方法を信頼できるものにする:</strong>方形枠の大きさを一定にする。同じ方形枠で同時に非生物的変数を測る。位置の選択に偏りが出ないよう乱数を使う。別の場所でも繰り返して平均を比べる。</p><div class=\"note\"><strong>採点基準の表現:</strong>「相関は因果関係を示さない」「トランセクトに沿って別の変数も変化している（交絡変数）」「パターンが信頼できるか確かめるため繰り返す」。<em>r</em>の符号は向き、大きさは強さを表します。</div>", "<p><strong>線樣帶還是帶狀樣帶？</strong><em>線樣帶 (line transect)</em> 只記錄接觸捲尺的生物；<em>帶狀樣帶 (belt transect)</em> 沿捲尺放置樣方，每個地點數據較多但工作量較大。兩者都顯示沿梯度的變化。</p><p><strong>計算示例。</strong>沿樣帶五個樣方的覆蓋百分率 (percentage cover) 為60、45、25、10和2 %。平均覆蓋率 = (60 + 45 + 25 + 10 + 2) / 5 = 28.4 %。重複調查可得到第二組數值作比較。</p><p><strong>解讀 r 和 R²。</strong>相關係數 (correlation coefficient) <em>r</em> 介乎-1至+1。</p><ul><li>+0.92（正）：光愈強，覆蓋愈大，是強正相關。</li><li>-0.88（負）：土壤鹽度愈高，覆蓋愈小。</li><li>接近0：沒有線性關係。</li><li>趨勢線的R²（如0.85）顯示直線與數據點的吻合程度。愈接近1愈吻合；0.85表示直線解釋了約85 %的變化。</li></ul><p><strong>令方法更可靠：</strong>樣方大小一致；在同一樣方、同一時間測量非生物變量；用隨機數字選位置以避免偏差；在其他地方重複樣帶調查再比較平均值。</p><div class=\"note\"><strong>評分準則用語：</strong>「相關性不代表因果關係」；「沿樣帶還有另一個變量在改變（混淆變量）」；「重複實驗以檢查規律是否可靠」。<em>r</em>的正負表示方向，大小表示強度。</div>"),
      heading: L("Limiting factors and transects (skills)", "制限要因とトランセクト（技能）", "限制因素與樣帶（技能）"),
      body: L(
        "<p>A <strong>limiting factor</strong> is a variable that restricts where a species can live or how well it grows, because its value is close to (or beyond) the edge of the species' range of tolerance. A species is found only where every factor, including the limiting one, lies within its range of tolerance.</p><figure><svg viewBox=\"0 0 360 180\" width=\"100%\" role=\"img\" aria-label=\"Tolerance curve: growth against value of an abiotic factor with optimum, stress zones and limits\" style=\"max-width:480px;font-family:var(--font-body,sans-serif)\"><rect x=\"40\" y=\"10\" width=\"300\" height=\"130\" fill=\"none\" stroke=\"var(--line,#c3d0d7)\"/><path d=\"M70 140 C120 130 130 30 190 25 C250 30 260 130 310 140\" fill=\"var(--good-soft,#d6f0e0)\" stroke=\"var(--good,#2a9d5c)\" stroke-width=\"2\"/><g stroke=\"var(--muted,#4d626d)\" stroke-dasharray=\"3 3\"><line x1=\"70\" y1=\"10\" x2=\"70\" y2=\"140\"/><line x1=\"310\" y1=\"10\" x2=\"310\" y2=\"140\"/><line x1=\"135\" y1=\"10\" x2=\"135\" y2=\"140\"/><line x1=\"245\" y1=\"10\" x2=\"245\" y2=\"140\"/></g><g font-size=\"9\" fill=\"var(--ink,#0f2029)\" text-anchor=\"middle\"><text x=\"190\" y=\"20\">optimum</text><text x=\"102\" y=\"60\">stress</text><text x=\"278\" y=\"60\">stress</text><text x=\"55\" y=\"100\" transform=\"rotate(-90 55 100)\">cannot survive</text><text x=\"325\" y=\"100\" transform=\"rotate(90 325 100)\">cannot survive</text><text x=\"190\" y=\"158\">range of tolerance (between the two limits)</text><text x=\"190\" y=\"174\" fill=\"var(--muted,#4d626d)\">value of abiotic factor (e.g. temperature) →</text></g></svg><figcaption>Growth or survival plotted against an abiotic factor. Illustrative curve.</figcaption></figure><p><strong>Application of skills: transects.</strong> A <strong>transect</strong> is a line across a habitat along which you record organisms and abiotic variables. This shows how distribution changes along an environmental gradient.</p><ol><li>Lay a tape measure across the habitat (for example from the sea inland over a dune system).</li><li>Place quadrats (square frames) at regular intervals along the line (systematic sampling), or at random positions chosen using random numbers (random sampling).</li><li>In each quadrat record the abundance or percentage cover of the species, and measure an abiotic variable (for example soil pH, light intensity or temperature with a sensor).</li><li>Graph the results and look for a <strong>correlation</strong> between the species and the variable. Correlation is not proof of cause, so look for supporting evidence.</li></ol><p>The guide expects you to collect transect data yourself in a natural or semi-natural habitat. A semi-natural habitat has been influenced by humans but is dominated by wild, not cultivated, species (such as a meadow or woodland).</p>",
        "<p><strong>制限要因 (limiting factor)</strong> とは、その値が種の耐性の範囲の端に近い（または範囲の外にある）ために、種の生息場所や成長を制限する要因です。種は、制限要因を含むすべての要因が耐性の範囲内にある場所にしか見られません。</p><figure><svg viewBox=\"0 0 360 180\" width=\"100%\" role=\"img\" aria-label=\"耐性曲線\" style=\"max-width:480px;font-family:var(--font-body,sans-serif)\"><rect x=\"40\" y=\"10\" width=\"300\" height=\"130\" fill=\"none\" stroke=\"var(--line,#c3d0d7)\"/><path d=\"M70 140 C120 130 130 30 190 25 C250 30 260 130 310 140\" fill=\"var(--good-soft,#d6f0e0)\" stroke=\"var(--good,#2a9d5c)\" stroke-width=\"2\"/><g stroke=\"var(--muted,#4d626d)\" stroke-dasharray=\"3 3\"><line x1=\"70\" y1=\"10\" x2=\"70\" y2=\"140\"/><line x1=\"310\" y1=\"10\" x2=\"310\" y2=\"140\"/><line x1=\"135\" y1=\"10\" x2=\"135\" y2=\"140\"/><line x1=\"245\" y1=\"10\" x2=\"245\" y2=\"140\"/></g><g font-size=\"9\" fill=\"var(--ink,#0f2029)\" text-anchor=\"middle\"><text x=\"190\" y=\"20\">最適 (optimum)</text><text x=\"102\" y=\"60\">ストレス</text><text x=\"278\" y=\"60\">ストレス</text><text x=\"55\" y=\"100\" transform=\"rotate(-90 55 100)\">生存不可</text><text x=\"325\" y=\"100\" transform=\"rotate(90 325 100)\">生存不可</text><text x=\"190\" y=\"158\">耐性の範囲 (range of tolerance)</text><text x=\"190\" y=\"174\" fill=\"var(--muted,#4d626d)\">非生物的要因の値（例: 温度）→</text></g></svg><figcaption>非生物的要因に対する成長または生存。説明用の曲線。</figcaption></figure><p><strong>技能の応用: トランセクト。</strong> <strong>トランセクト (transect)</strong> は、生息地を横切る線に沿って生物と非生物的変数を記録する方法で、環境の傾度に沿った分布の変化がわかります。</p><ol><li>生息地を横切ってメジャーを張る（例: 砂丘で海から内陸へ）。</li><li>線に沿って一定間隔でコドラート（方形枠）を置く（系統的サンプリング）、または乱数で選んだ位置に置く（ランダムサンプリング）。</li><li>各コドラートで種の個体数または被度（％）を記録し、非生物的変数（土壌pH、光の強さ、センサーによる温度など）を測定する。</li><li>結果をグラフにして、種と変数の間の<strong>相関 (correlation)</strong> を探す。相関は原因の証明ではないので、裏づけを探す。</li></ol><p>指針は、自然または半自然の生息地で自分でトランセクトのデータを集めることを求めています。半自然の生息地とは、人間の影響を受けているが栽培種ではなく野生種が優占する場所（草地や森林など）です。</p>",
        "<p><strong>限制因素 (limiting factor)</strong> 是因數值接近（或超出）物種耐受範圍的邊緣，而限制物種在哪裏生活或生長得多好的因素。只有當所有因素（包括限制因素）都處於耐受範圍之內，物種才會出現。</p><figure><svg viewBox=\"0 0 360 180\" width=\"100%\" role=\"img\" aria-label=\"耐受曲線\" style=\"max-width:480px;font-family:var(--font-body,sans-serif)\"><rect x=\"40\" y=\"10\" width=\"300\" height=\"130\" fill=\"none\" stroke=\"var(--line,#c3d0d7)\"/><path d=\"M70 140 C120 130 130 30 190 25 C250 30 260 130 310 140\" fill=\"var(--good-soft,#d6f0e0)\" stroke=\"var(--good,#2a9d5c)\" stroke-width=\"2\"/><g stroke=\"var(--muted,#4d626d)\" stroke-dasharray=\"3 3\"><line x1=\"70\" y1=\"10\" x2=\"70\" y2=\"140\"/><line x1=\"310\" y1=\"10\" x2=\"310\" y2=\"140\"/><line x1=\"135\" y1=\"10\" x2=\"135\" y2=\"140\"/><line x1=\"245\" y1=\"10\" x2=\"245\" y2=\"140\"/></g><g font-size=\"9\" fill=\"var(--ink,#0f2029)\" text-anchor=\"middle\"><text x=\"190\" y=\"20\">最適值 (optimum)</text><text x=\"102\" y=\"60\">壓力區</text><text x=\"278\" y=\"60\">壓力區</text><text x=\"55\" y=\"100\" transform=\"rotate(-90 55 100)\">不能存活</text><text x=\"325\" y=\"100\" transform=\"rotate(90 325 100)\">不能存活</text><text x=\"190\" y=\"158\">耐受範圍 (range of tolerance)</text><text x=\"190\" y=\"174\" fill=\"var(--muted,#4d626d)\">非生物因素的數值（例如溫度）→</text></g></svg><figcaption>生長或存活與非生物因素的關係。示意曲線。</figcaption></figure><p><strong>技能應用：樣帶 (transect)。</strong><strong>樣帶</strong>是橫過生境的一條線，沿線記錄生物和非生物變量，可顯示分佈如何沿環境梯度變化。</p><ol><li>橫過生境拉一條捲尺（例如在沙丘系統中由海邊向內陸）。</li><li>沿線以固定間距放置樣方 (quadrat，方形框)（系統抽樣），或用隨機數字決定位置放置（隨機抽樣）。</li><li>在每個樣方記錄物種的數量或覆蓋百分率，並量度一個非生物變量（例如用感應器量度土壤pH、光強度或溫度）。</li><li>把結果繪成圖，尋找物種與該變量之間的<strong>相關性 (correlation)</strong>。相關性並不證明因果，所以要尋找支持的證據。</li></ol><p>指引期望你在自然或半自然生境自行收集樣帶數據。半自然生境曾受人類影響，但以野生而非栽培物種為主（例如草地或林地）。</p>"
      ),
      examTip: L("Correlation does not prove cause. In a transect question, describe the pattern with numbers, then suggest an abiotic variable, and say what extra evidence you would need.", "相関は原因の証明ではありません。トランセクトの問題では、数値を使ってパターンを述べ、非生物的変数を挙げ、必要な追加の証拠を述べます。", "相關性不等於因果。樣帶題要用數字描述規律，提出一個非生物變量，並說明還需要甚麼額外證據。")
    },
    {
      ref: "B4.1.5", ahl: false,
      deeperTitle: L("Why each reef condition matters: cause and effect", "サンゴ礁の条件がなぜ重要か: 原因と結果", "為何每項珊瑚礁條件都重要：因果關係"),
      deeper: L("<p><strong>The key link is light.</strong> Reef-building corals contain photosynthetic algae. The algae photosynthesise and pass organic compounds to the coral, and the coral gives the algae shelter and some of the substances they need. Corals therefore behave like partly photosynthetic organisms, so anything that cuts light cuts the reef.</p><table><tr><th>If this changes</th><th>Direct effect</th><th>Result for the reef</th></tr><tr><td>Water is deeper</td><td>Less light reaches the algae</td><td>Less photosynthesis, so slower coral growth and skeleton building</td></tr><tr><td>Water is cloudy (sediment)</td><td>Light is absorbed or scattered; particles settle on coral</td><td>Less light and smothering, so reefs are rare near the mouths of muddy rivers</td></tr><tr><td>Water is much cooler</td><td>Outside the temperature range for growth</td><td>Reefs are mostly found in warm, tropical seas</td></tr><tr><td>Salinity falls (river water)</td><td>Salt concentration outside the tolerance range</td><td>Corals are stressed or die</td></tr><tr><td>Water becomes more acidic</td><td>Calcium carbonate dissolves more easily</td><td>Harder to build and keep the skeleton</td></tr></table><p>River mouths combine two problems at once: lower salinity <em>and</em> sediment. This is a good example of several factors acting together.</p><div class=\"note\"><strong>Mark-scheme language:</strong> give the condition, then the reason, for example \"shallow, so enough light reaches the photosynthetic algae in the coral\". Threats to reefs belong to D4.3, not here.</div>", "<p><strong>鍵となるのは光です。</strong>造礁サンゴは光合成をする藻類を含みます。藻類は光合成をして有機物をサンゴに渡し、サンゴは藻類に住みかと必要な物質の一部を与えます。そのためサンゴは部分的に光合成をする生物のように振る舞い、光を減らすものはサンゴ礁を減らします。</p><table><tr><th>これが変わると</th><th>直接の影響</th><th>サンゴ礁への結果</th></tr><tr><td>水が深くなる</td><td>藻類に届く光が減る</td><td>光合成が減り、サンゴの成長と骨格形成が遅くなる</td></tr><tr><td>水が濁る（堆積物）</td><td>光が吸収・散乱され、粒子がサンゴに降り積もる</td><td>光が減り、覆われてしまう。泥の多い河口の近くにサンゴ礁がまれな理由</td></tr><tr><td>水がかなり冷たくなる</td><td>成長に適した温度の範囲外になる</td><td>サンゴ礁はおもに温かい熱帯の海にある</td></tr><tr><td>塩分が下がる（河川水）</td><td>塩濃度が耐性の範囲外になる</td><td>サンゴがストレスを受けるか死ぬ</td></tr><tr><td>水がより酸性になる</td><td>炭酸カルシウムが溶けやすくなる</td><td>骨格をつくり維持することが難しくなる</td></tr></table><p>河口では、塩分の低下<em>と</em>堆積物という2つの問題が同時に起こります。複数の要因が一緒に働くよい例です。</p><div class=\"note\"><strong>採点基準の表現:</strong>条件を述べ、次に理由を述べます。例:「浅いので、サンゴ内の光合成をする藻類に十分な光が届く」。サンゴ礁への脅威はここではなくD4.3で学びます。</div>", "<p><strong>關鍵在於光。</strong>造礁珊瑚含有進行光合作用的藻類。藻類光合作用後把有機物交給珊瑚，珊瑚則為藻類提供庇護和部分所需物質。因此珊瑚的行為像部分行光合作用的生物，任何減少光線的因素都會減少珊瑚礁。</p><table><tr><th>若這項改變</th><th>直接影響</th><th>對珊瑚礁的結果</th></tr><tr><td>水較深</td><td>到達藻類的光減少</td><td>光合作用減少，珊瑚生長和造骨變慢</td></tr><tr><td>水混濁（沉積物）</td><td>光被吸收或散射；顆粒沉積在珊瑚上</td><td>光減少並被掩蓋，所以多泥河口附近很少珊瑚礁</td></tr><tr><td>水溫低很多</td><td>超出生長所需的溫度範圍</td><td>珊瑚礁大多見於溫暖的熱帶海洋</td></tr><tr><td>鹽度下降（河水）</td><td>鹽濃度超出耐受範圍</td><td>珊瑚受壓或死亡</td></tr><tr><td>水變得較酸</td><td>碳酸鈣較易溶解</td><td>較難建造和維持骨骼</td></tr></table><p>河口同時有兩個問題：鹽度較低<em>及</em>沉積物。這是多個因素同時作用的好例子。</p><div class=\"note\"><strong>評分準則用語：</strong>先寫條件，再寫原因，例如「水淺，所以足夠的光到達珊瑚內進行光合作用的藻類」。珊瑚礁面對的威脅屬於D4.3，不在此處。</div>"),
      heading: L("Conditions for coral reef formation", "サンゴ礁の形成に必要な条件", "珊瑚礁形成的條件"),
      body: L(
        "<p>Coral reefs are an example of a <strong>marine ecosystem</strong>. Reef-building corals are animals that build a hard skeleton of calcium carbonate. Their tissues contain photosynthetic algae. The guide lists these factors:</p><table><tr><th>Factor</th><th>Condition for reef formation</th><th>Why</th></tr><tr><td>Water depth</td><td>Shallow (roughly the top tens of metres)</td><td>Light is needed for the photosynthetic algae in the coral</td></tr><tr><td>Clarity</td><td>Clear water</td><td>Allows light to penetrate. Sediment would block light and smother coral</td></tr><tr><td>Temperature</td><td>Warm water (roughly 20–30 °C)</td><td>Corals grow and build skeletons well when warm. Too hot causes stress and bleaching</td></tr><tr><td>Salinity</td><td>Normal sea water</td><td>Corals cannot tolerate large drops in salt concentration (for example near river mouths)</td></tr><tr><td>pH</td><td>Slightly alkaline sea water</td><td>Skeletons are calcium carbonate, which dissolves more easily as the water becomes more acidic</td></tr></table>",
        "<p>サンゴ礁は<strong>海洋生態系</strong>の例です。造礁サンゴは炭酸カルシウムの硬い骨格をつくる動物で、組織内に光合成をする藻類をもっています。指針は次の要因を挙げています。</p><table><tr><th>要因</th><th>サンゴ礁形成の条件</th><th>理由</th></tr><tr><td>水深</td><td>浅い（おおよそ表層の数十メートル）</td><td>サンゴ内の光合成藻類に光が必要</td></tr><tr><td>透明度</td><td>澄んだ水</td><td>光が届く。堆積物は光をさえぎりサンゴをおおってしまう</td></tr><tr><td>温度</td><td>暖かい水（おおよそ20〜30 °C）</td><td>暖かいとよく成長し骨格をつくる。高すぎるとストレスや白化が起こる</td></tr><tr><td>塩分</td><td>通常の海水</td><td>塩分濃度の大きな低下（河口付近など）に耐えられない</td></tr><tr><td>pH</td><td>弱アルカリ性の海水</td><td>骨格は炭酸カルシウムで、水が酸性に傾くと溶けやすくなる</td></tr></table>",
        "<p>珊瑚礁是<strong>海洋生態系統</strong>的例子。造礁珊瑚是動物，會建造碳酸鈣的堅硬骨骼，其組織內含進行光合作用的藻類。指引列出以下因素：</p><table><tr><th>因素</th><th>珊瑚礁形成的條件</th><th>原因</th></tr><tr><td>水深</td><td>淺水（大約表層數十米）</td><td>珊瑚內的光合藻類需要光</td></tr><tr><td>清澈度</td><td>清澈的水</td><td>讓光線穿透；沉積物會阻擋光線並覆蓋珊瑚</td></tr><tr><td>溫度</td><td>溫暖的水（大約20–30 °C）</td><td>溫暖時珊瑚生長良好並建造骨骼；過熱會引致壓力和白化</td></tr><tr><td>鹽度</td><td>正常海水</td><td>珊瑚不能耐受鹽濃度大幅下降（例如河口附近）</td></tr><tr><td>pH</td><td>微鹼性海水</td><td>骨骼是碳酸鈣，水越酸越容易溶解</td></tr></table>"
      )
    },
    {
      ref: "B4.1.6", ahl: false,
      deeperTitle: L("Using the biome graph: worked examples", "バイオーム図の使い方: 例題", "運用生物群系圖：實例"),
      deeper: L("<p><strong>Method:</strong> (1) find the temperature on the horizontal axis; (2) find the rainfall on the vertical axis; (3) read the region where they meet; (4) name the biome and quote both values. Using the graph above (boundaries are approximate):</p><table><tr><th>Site</th><th>Temperature, rainfall</th><th>Biome</th><th>Reasoning</th></tr><tr><td>A</td><td>26 °C, 2500 mm</td><td>Tropical forest</td><td>Hot and very wet</td></tr><tr><td>B</td><td>26 °C, 150 mm</td><td>Hot desert</td><td>Same temperature as A, but very little rain</td></tr><tr><td>C</td><td>-12 °C, 200 mm</td><td>Tundra</td><td>Very cold and dry</td></tr><tr><td>D</td><td>-8 °C, 700 mm</td><td>Taiga</td><td>Cold, but more precipitation than C</td></tr><tr><td>E</td><td>12 °C, 1500 mm</td><td>Temperate forest</td><td>Mild, moist</td></tr></table><p>Comparing A with B shows that <strong>rainfall alone</strong> can change the biome; comparing C with D shows the same at low temperature.</p><ul><li><strong>Why temperature matters:</strong> it sets how long and how fast plants can grow, and how fast water evaporates.</li><li><strong>Why rainfall matters:</strong> it sets how much water is available to plants.</li><li>The regions overlap on the graph because other factors (soil, fire, grazing) can decide which biome develops where the climate lies near a boundary.</li></ul><div class=\"note\"><strong>Mark-scheme language:</strong> \"temperature and rainfall (abiotic factors) largely determine the biome\"; \"for a given temperature and rainfall, one ecosystem type is likely to develop\".</div>", "<p><strong>手順:</strong>(1) 横軸で気温を見つける。(2) 縦軸で降水量を見つける。(3) 2つが交わる領域を読む。(4) バイオーム名を答え、両方の値を引用する。上の図（境界は近似）を使うと:</p><table><tr><th>地点</th><th>気温、降水量</th><th>バイオーム</th><th>理由</th></tr><tr><td>A</td><td>26 °C、2500 mm</td><td>熱帯林 (tropical forest)</td><td>高温で非常に多雨</td></tr><tr><td>B</td><td>26 °C、150 mm</td><td>砂漠 (hot desert)</td><td>Aと同じ気温だが雨がとても少ない</td></tr><tr><td>C</td><td>-12 °C、200 mm</td><td>ツンドラ (tundra)</td><td>非常に寒く乾燥</td></tr><tr><td>D</td><td>-8 °C、700 mm</td><td>タイガ (taiga)</td><td>寒いがCより降水量が多い</td></tr><tr><td>E</td><td>12 °C、1500 mm</td><td>温帯林 (temperate forest)</td><td>温和で湿潤</td></tr></table><p>AとBの比較から、<strong>降水量だけ</strong>でバイオームが変わることがわかり、CとDの比較から、低温でも同じことがわかります。</p><ul><li><strong>気温が重要な理由:</strong>植物がどれだけ長く速く成長できるか、水がどれだけ速く蒸発するかを決める。</li><li><strong>降水量が重要な理由:</strong>植物が使える水の量を決める。</li><li>図で領域が重なるのは、気候が境界付近にあるとき、土壌・火・採食など他の要因がどのバイオームができるかを決めうるからです。</li></ul><div class=\"note\"><strong>採点基準の表現:</strong>「気温と降水量（非生物的要因）が大部分バイオームを決める」「ある気温と降水量では、1つの生態系タイプができやすい」。</div>", "<p><strong>方法：</strong>(1) 在橫軸找出溫度；(2) 在縱軸找出雨量；(3) 讀出兩者相交的區域；(4) 說出生物群系並引用兩個數值。使用上圖（邊界為約數）：</p><table><tr><th>地點</th><th>溫度、雨量</th><th>生物群系</th><th>推理</th></tr><tr><td>A</td><td>26 °C、2500 mm</td><td>熱帶森林 (tropical forest)</td><td>炎熱而極多雨</td></tr><tr><td>B</td><td>26 °C、150 mm</td><td>熱帶沙漠 (hot desert)</td><td>溫度與A相同，但雨量極少</td></tr><tr><td>C</td><td>-12 °C、200 mm</td><td>苔原 (tundra)</td><td>極寒冷而乾燥</td></tr><tr><td>D</td><td>-8 °C、700 mm</td><td>針葉林 (taiga)</td><td>寒冷，但降水量比C多</td></tr><tr><td>E</td><td>12 °C、1500 mm</td><td>溫帶森林 (temperate forest)</td><td>溫和濕潤</td></tr></table><p>比較A和B，可見<strong>單是雨量</strong>已可改變生物群系；比較C和D，可見低溫時也一樣。</p><ul><li><strong>溫度為何重要：</strong>它決定植物生長的時間長短和速度，以及水分蒸發的快慢。</li><li><strong>雨量為何重要：</strong>它決定植物可利用的水量。</li><li>圖中各區域重疊，是因為氣候接近邊界時，土壤、火燒和被啃食等其他因素也可能決定發展出哪種生物群系。</li></ul><div class=\"note\"><strong>評分準則用語：</strong>「溫度和雨量（非生物因素）在很大程度上決定生物群系」；「在特定的溫度和雨量下，很可能發展出一種生態系統類型」。</div>"),
      heading: L("Climate decides which biome develops", "気候がバイオームを決める", "氣候決定生物群系"),
      body: {
        en: "<p>A <strong>biome</strong> is a large region with a characteristic type of natural ecosystem, such as forest or desert. For any given temperature and rainfall pattern, <strong>one natural ecosystem type is likely to develop</strong>. So temperature and rainfall (abiotic factors) largely determine the distribution of terrestrial biomes.</p><p>The guide asks you to illustrate this with a graph that has these two variables on the axes. Temperature is on the horizontal axis and rainfall on the vertical axis.</p>" + CL.en + "<p>How to read it: hot and wet gives tropical forest; hot and dry gives hot desert; cold gives tundra or taiga. At intermediate temperatures, more rain favours forest and less rain favours grassland.</p>",
        ja: "<p><strong>バイオーム (biome)</strong> とは、森林や砂漠のような特徴的な自然生態系をもつ広い地域です。ある気温と降水のパターンのもとでは、<strong>ほぼ1つの自然生態系のタイプが成立します</strong>。したがって、気温と降水量（非生物的要因）が陸上バイオームの分布をほぼ決めます。</p><p>指針は、この2つの変数を軸にしたグラフで示すよう求めています。横軸が気温、縦軸が降水量です。</p>" + CL.ja + "<p>読み方: 高温で多雨なら熱帯林、高温で乾燥なら熱帯砂漠、寒ければツンドラかタイガ。中間の気温では、降水が多いと森林、少ないと草原になりやすい。</p>",
        zh: "<p><strong>生物群系 (biome)</strong> 是具有某種特有自然生態系統（如森林或沙漠）的廣大地區。在某一特定的溫度和雨量型態下，<strong>很可能形成一種自然生態系統類型</strong>。因此氣溫和雨量（非生物因素）在很大程度上決定陸地生物群系的分佈。</p><p>指引要求你用一幅以這兩個變量為軸的圖來說明：橫軸是氣溫，縱軸是雨量。</p>" + CL.zh + "<p>讀圖方法：又熱又濕是熱帶森林；又熱又乾是熱帶沙漠；寒冷是苔原或針葉林。在中等溫度下，雨量多有利森林，雨量少有利草原。</p>"
      },
      examTip: L("If given a climatograph, read the temperature and rainfall of the site, then find the region of the graph it falls in. Quote both values.", "気候図が与えられたら、地点の気温と降水量を読み取り、グラフ上のどの領域に入るかを探します。両方の値を引用しましょう。", "題目給你氣候圖時，讀取該地的溫度和雨量，找出它落在圖中哪個區域，並引用兩個數值。")
    },
    {
      ref: "B4.1.7", ahl: false,
      deeperTitle: L("How convergent evolution works, and biome versus ecosystem", "収れん進化のしくみ、バイオームと生態系", "趨同演化如何發生；生物群系與生態系統"),
      deeper: L("<p><strong>Convergent evolution, step by step:</strong></p><ol><li>Unrelated species live in separate places with the <strong>same abiotic conditions</strong>, so they face similar selection pressures.</li><li>In each population there is <strong>variation</strong>; some individuals happen to be better suited (for example they lose less water).</li><li>These individuals survive and reproduce more, passing on the genes for the helpful trait.</li><li>Over many generations <strong>each lineage independently</strong> evolves a similar feature. The result is <strong>analogous</strong> structures (similar function, different ancestry), not inherited from a common ancestor with that feature.</li></ol><table><tr><th></th><th>Biome</th><th>Ecosystem</th></tr><tr><td>Scale</td><td>Large region, often on several continents</td><td>One community and its abiotic environment in one place</td></tr><tr><td>Example</td><td>Tropical forest</td><td>The rainforest in the Amazon basin</td></tr><tr><td>Species</td><td>Many different species in different places</td><td>The actual species living there</td></tr></table><p>A biome therefore contains many separate ecosystems, such as the rainforests of South America, Africa and South-East Asia. These share a climate and a similar look, but most of their species differ.</p><div class=\"note\"><strong>Mark-scheme language:</strong> \"unrelated species\"; \"similar selection pressures\"; \"evolved similar adaptations independently\". Do not say the organisms \"adapted\" in their own lifetime, or that they \"share a recent ancestor\".</div>", "<p><strong>収れん進化 (convergent evolution) を順に:</strong></p><ol><li>類縁のない種が、<strong>同じ非生物的条件</strong>をもつ別々の場所にすみ、似た選択圧を受ける。</li><li>各個体群には<strong>変異</strong>があり、たまたま環境によく合う個体がいる（例: 水の損失が少ない）。</li><li>そうした個体は生き残って多く繁殖し、有利な形質の遺伝子を伝える。</li><li>何世代もかけて、<strong>それぞれの系統が独立に</strong>似た特徴を進化させる。その結果は、共通祖先から受け継いだのではない<strong>相似</strong> (analogous) 構造（機能は似るが由来は異なる）です。</li></ol><table><tr><th></th><th>バイオーム (biome)</th><th>生態系 (ecosystem)</th></tr><tr><td>規模</td><td>広い地域。複数の大陸にまたがることが多い</td><td>1か所の群集とその非生物的環境</td></tr><tr><td>例</td><td>熱帯林</td><td>アマゾン川流域の熱帯雨林</td></tr><tr><td>種</td><td>場所ごとに異なる多くの種</td><td>そこにすむ実際の種</td></tr></table><p>したがって1つのバイオームには、南米・アフリカ・東南アジアの熱帯雨林のように、多くの別々の生態系が含まれます。気候と見た目は似ていますが、種の大部分は異なります。</p><div class=\"note\"><strong>採点基準の表現:</strong>「類縁のない種」「似た選択圧」「似た適応を独立に進化させた」。生物が一生のうちに「適応した」とか、「近い共通祖先をもつ」とは書かないこと。</div>", "<p><strong>趨同演化 (convergent evolution) 逐步說明：</strong></p><ol><li>親緣疏遠的物種生活在不同地方，但那裏的<strong>非生物條件相同</strong>，所以面對相似的選擇壓力。</li><li>每個種群都有<strong>變異</strong>，有些個體碰巧較適應（例如失水較少）。</li><li>這些個體存活和繁殖較多，把有利性狀的基因傳下去。</li><li>經過許多世代，<strong>各個譜系獨立地</strong>演化出相似特徵。結果是<strong>同功</strong> (analogous) 結構（功能相似、來源不同），並非由具備該特徵的共同祖先遺傳而來。</li></ol><table><tr><th></th><th>生物群系 (biome)</th><th>生態系統 (ecosystem)</th></tr><tr><td>規模</td><td>大範圍地區，常跨越幾個大陸</td><td>某一處的一個群落及其非生物環境</td></tr><tr><td>例子</td><td>熱帶森林</td><td>亞馬遜盆地的雨林</td></tr><tr><td>物種</td><td>不同地方有許多不同物種</td><td>實際生活在那裏的物種</td></tr></table><p>因此一個生物群系包含許多獨立的生態系統，例如南美洲、非洲和東南亞的雨林。它們氣候相同、外觀相似，但大部分物種不同。</p><div class=\"note\"><strong>評分準則用語：</strong>「親緣疏遠的物種」；「相似的選擇壓力」；「獨立演化出相似的適應特徵」。不要寫生物在一生中自己「適應了」，也不要寫它們「有近期的共同祖先」。</div>"),
      heading: L("Biomes and convergent evolution", "バイオームと収れん進化", "生物群系與趨同演化"),
      body: L(
        "<p>A <strong>biome</strong> is a group of ecosystems with <strong>similar communities</strong> because they have <strong>similar abiotic conditions</strong>. Ecosystems on different continents can look alike because of <strong>convergent evolution</strong>. Unrelated species that face the same selection pressures evolve similar adaptations independently (for example, spiny, water-storing stems in cacti of the Americas and in unrelated euphorbs of Africa).</p><p>You should know the climate conditions of six biomes (approximate values):</p><table><tr><th>Biome</th><th>Climate</th></tr><tr><td>Tropical forest</td><td>Hot all year; very high rainfall, usually over about 2000 mm a year; little seasonal change</td></tr><tr><td>Temperate forest</td><td>Mild; four seasons; moderate to high rainfall spread through the year</td></tr><tr><td>Taiga</td><td>Long, very cold winters; short, cool summers; moderate to low precipitation, much of it snow</td></tr><tr><td>Grassland</td><td>Moderate rainfall, often seasonal, with dry periods; too dry for continuous forest</td></tr><tr><td>Tundra</td><td>Very cold; short, cool summer; low precipitation; ground frozen (permafrost) below the surface</td></tr><tr><td>Hot desert</td><td>Hot by day; very low and unreliable rainfall, below about 250 mm a year</td></tr></table>",
        "<p><strong>バイオーム (biome)</strong> は、<strong>似た非生物的条件</strong>のために<strong>似た群集</strong>をもつ生態系のまとまりです。異なる大陸の生態系が似て見えるのは<strong>収れん進化 (convergent evolution)</strong> のためです。同じ選択圧に直面した類縁のない種が、独立に似た適応を進化させます（例: アメリカ大陸のサボテンとアフリカの無関係なトウダイグサ類にみられる、トゲがあり水をたくわえる茎）。</p><p>6つのバイオームの気候条件を知っておく必要があります（おおよその値）。</p><table><tr><th>バイオーム</th><th>気候</th></tr><tr><td>熱帯林</td><td>一年中高温。降水量が非常に多く、通常年およそ2000 mm超。季節変化が小さい</td></tr><tr><td>温帯林</td><td>温和。四季があり、降水は中程度〜多く年間を通じてある</td></tr><tr><td>タイガ</td><td>長く非常に寒い冬、短く涼しい夏。降水は中程度〜少なく、多くは雪</td></tr><tr><td>草原</td><td>降水は中程度で、しばしば季節的に乾期がある。連続した森林ができるには乾燥しすぎ</td></tr><tr><td>ツンドラ</td><td>非常に寒い。短く涼しい夏。降水が少ない。地下は凍結（永久凍土）</td></tr><tr><td>熱帯砂漠</td><td>昼は高温。降水が非常に少なく不安定で、年およそ250 mm未満</td></tr></table>",
        "<p><strong>生物群系 (biome)</strong> 是因<strong>非生物條件相似</strong>而擁有<strong>相似群落</strong>的一組生態系統。不同大陸的生態系統看似相像，是由於<strong>趨同演化 (convergent evolution)</strong>：親緣關係疏遠的物種面對相同的選擇壓力，各自獨立演化出相似的適應特徵（例如美洲仙人掌與非洲無親緣關係的大戟屬植物都有帶刺、儲水的莖）。</p><p>你要掌握六種生物群系的氣候條件（約數）：</p><table><tr><th>生物群系</th><th>氣候</th></tr><tr><td>熱帶森林</td><td>全年炎熱；雨量極高，通常每年約2000 mm以上；季節變化小</td></tr><tr><td>溫帶森林</td><td>溫和；有四季；雨量中等至高，全年分佈</td></tr><tr><td>針葉林 (taiga)</td><td>冬季漫長而極寒，夏季短而涼；降水量中等至低，大部分是雪</td></tr><tr><td>草原</td><td>雨量中等，常有季節性乾旱期；太乾而不能形成連續森林</td></tr><tr><td>苔原</td><td>極寒；夏季短而涼；降水少；地下凍結（永凍土）</td></tr><tr><td>熱帶沙漠</td><td>日間炎熱；雨量極低且不穩定，每年低於約250 mm</td></tr></table>"
      )
    },
    {
      ref: "B4.1.8", ahl: false,
      deeperTitle: L("Desert and rainforest adaptations: problem, feature, how it works", "砂漠と熱帯雨林の適応: 問題・特徴・仕組み", "沙漠與熱帶雨林的適應：難題、特徵、運作方式"),
      deeper: L("<table><tr><th>Species</th><th>Problem</th><th>Adaptation</th><th>How it helps</th></tr><tr><td>Saguaro cactus</td><td>Rain is rare and brief</td><td>Pleated, fleshy stem; shallow, wide roots</td><td>Roots soak up rain quickly; the stem swells with stored water between rains. Spines replace leaves, so less surface for water loss.</td></tr><tr><td>Dromedary camel</td><td>Little water, heat</td><td>Concentrated urine, dry faeces; body temperature allowed to rise by day</td><td>Less water lost in excretion, and less sweating is needed because the body does not try to stay cool at all costs.</td></tr><tr><td>Kangaroo rat</td><td>Heat by day</td><td>Burrows by day, active at night</td><td>Avoids the hottest, driest air. Water comes from food and from respiration.</td></tr><tr><td>Buttress-rooted tree</td><td>Thin soil, tall trunk</td><td>Wide buttress roots</td><td>Spread the load and support the trunk.</td></tr><tr><td>Orchid (epiphyte)</td><td>Dark forest floor</td><td>Grows on branches, aerial roots</td><td>Reaches light in the canopy without needing soil.</td></tr><tr><td>Red-eyed tree frog</td><td>Predators, climbing</td><td>Sticky toe pads; green colour</td><td>Grips leaves and trunks; camouflage against green leaves.</td></tr></table><p><strong>Outline of a 4-mark answer</strong> (one named plant, one named animal, desert): name the plant; give one feature with its function; name the animal; give one feature with its function. Two names plus two feature-and-function pairs earn all four marks.</p><div class=\"note\"><strong>Mark-scheme language:</strong> \"reduces water loss\"; \"stores water\"; \"avoids the heat of the day\". Vague phrases such as \"it is adapted to the desert\" earn nothing. Do not say that the camel stores water in its hump (it is fat).</div>", "<table><tr><th>種</th><th>問題</th><th>適応</th><th>どう役立つか</th></tr><tr><td>サワロサボテン</td><td>雨がまれで短い</td><td>ひだのある多肉質の茎、浅く広い根</td><td>根が雨をすばやく吸い、茎は雨と雨の間にためた水でふくらむ。葉の代わりにトゲがあり、水が出る表面が少ない。</td></tr><tr><td>ヒトコブラクダ</td><td>水が少なく暑い</td><td>濃い尿と乾いたふん、昼は体温が上がるのを許す</td><td>排出で失う水が減り、体温を無理に保たないので発汗も少なくて済む。</td></tr><tr><td>カンガルーネズミ</td><td>昼の暑さ</td><td>昼は巣穴、夜に活動</td><td>最も暑く乾いた空気を避ける。水は食物と呼吸から得る。</td></tr><tr><td>板根をもつ木</td><td>薄い土壌、高い幹</td><td>広い板根 (buttress root)</td><td>荷重を分散して幹を支える。</td></tr><tr><td>ラン（着生植物）</td><td>暗い林床</td><td>枝の上に生え、気根をもつ</td><td>土壌なしで林冠の光に届く。</td></tr><tr><td>アカメアマガエル</td><td>捕食者、木登り</td><td>吸盤のある足指、緑色</td><td>葉や幹をつかむ。緑の葉に対する擬態（保護色）。</td></tr></table><p><strong>4点の答えの組み立て</strong>（砂漠の植物1種と動物1種）: 植物名、その特徴と機能、動物名、その特徴と機能。2つの名前と、2組の「特徴と機能」で4点です。</p><div class=\"note\"><strong>採点基準の表現:</strong>「水分の損失を減らす」「水をためる」「昼の暑さを避ける」。「砂漠に適応している」のような曖昧な言い方は得点になりません。ラクダのこぶに水がたまっているとは書かないこと（脂肪です）。</div>", "<table><tr><th>物種</th><th>難題</th><th>適應特徵</th><th>如何幫助</th></tr><tr><td>巨人柱仙人掌</td><td>雨少而短暫</td><td>有褶的多肉莖；淺而闊的根</td><td>根迅速吸收雨水，莖在兩次雨之間因貯水而膨脹；以刺代替葉，失水表面少。</td></tr><tr><td>單峰駱駝</td><td>缺水、炎熱</td><td>濃縮尿液、乾糞便；日間容許體溫上升</td><td>排泄失水較少；體溫不必不惜一切保持低溫，所以少出汗。</td></tr><tr><td>更格盧鼠</td><td>日間炎熱</td><td>日間躲在洞穴，夜間活動</td><td>避開最熱最乾的空氣；水來自食物和呼吸作用。</td></tr><tr><td>有板根的樹</td><td>土壤薄、樹幹高</td><td>寬大的板根 (buttress root)</td><td>分散重量，支撐樹幹。</td></tr><tr><td>蘭花（附生植物）</td><td>森林地面陰暗</td><td>長在樹枝上，有氣生根</td><td>無須土壤即可到達樹冠的光線。</td></tr><tr><td>紅眼樹蛙</td><td>天敵、攀爬</td><td>黏性趾墊；綠色</td><td>抓緊葉和樹幹；綠色在綠葉間偽裝。</td></tr></table><p><strong>4分答案的結構</strong>（沙漠中一種植物、一種動物）：寫出植物名稱；一項特徵及其功能；寫出動物名稱；一項特徵及其功能。兩個名稱加兩組「特徵與功能」可得滿分。</p><div class=\"note\"><strong>評分準則用語：</strong>「減少失水」；「儲水」；「避開日間炎熱」。「它適應了沙漠」之類含糊說法不得分。不要寫駱駝在駝峰儲水（駝峰儲的是脂肪）。</div>"),
      heading: L("Adaptations to hot deserts and tropical rainforest", "熱帯砂漠と熱帯雨林への適応", "對熱帶沙漠與熱帶雨林的適應"),
      body: L(
        "<p>You need examples of adaptations in <strong>named species</strong> of plants and animals for both biomes.</p><p><strong>Hot desert</strong> (problems: very little water, extreme heat):</p><ul><li><em>Saguaro cactus</em> (plant): thick fleshy stem stores water; leaves reduced to spines, which reduces water loss and deters herbivores; shallow, wide-spreading roots absorb brief rain quickly.</li><li><em>Dromedary camel</em> (animal): tolerates large water loss; produces concentrated urine and dry faeces; fat stored in the hump (not water); body temperature is allowed to rise during the day, reducing sweating.</li><li><em>Kangaroo rat</em> (animal): burrows by day and is nocturnal, avoiding heat; makes very concentrated urine; gets much of its water from its food and from respiration.</li><li><em>Fennec fox</em> (animal): large ears with many blood vessels lose heat; nocturnal; pale fur reflects light.</li></ul><p><strong>Tropical rainforest</strong> (problems: intense competition for light, constant heavy rain, many predators and herbivores):</p><ul><li>Many trees have <em>buttress roots</em> that support tall shallow-rooted trunks in thin soil.</li><li>Many leaves have <em>drip tips</em> that help shed water quickly.</li><li><em>Orchids</em> (plants) grow on branches (as epiphytes) with aerial roots, reaching light high in the canopy.</li><li><em>Red-eyed tree frog</em> (animal): sticky toe pads for climbing; green colour for camouflage among leaves.</li><li><em>Three-toed sloth</em> (animal): strong curved claws for hanging; slow movement and low energy needs; algae in its fur give it a green tinge, which camouflages it.</li></ul>",
        "<p>両方のバイオームについて、植物と動物の<strong>名前のある種</strong>の適応の例が必要です。</p><p><strong>熱帯砂漠</strong>（問題: 水がごく少ない、極度の高温）</p><ul><li><em>サワロサボテン (saguaro cactus)</em>（植物）: 厚い多肉質の茎が水をたくわえる。葉はトゲに退化し水分の損失を減らし、草食動物を防ぐ。浅く広がる根が短い雨をすばやく吸収する。</li><li><em>ヒトコブラクダ (dromedary camel)</em>（動物）: 大きな水分の損失に耐える。濃縮した尿と乾いた糞を出す。こぶには（水ではなく）脂肪がたくわえられる。日中は体温が上昇するのを許し、発汗を減らす。</li><li><em>カンガルーネズミ (kangaroo rat)</em>（動物）: 日中は巣穴にいて夜行性で、暑さを避ける。非常に濃い尿をつくる。水の多くを食物と呼吸から得る。</li><li><em>フェネック (fennec fox)</em>（動物）: 血管の多い大きな耳で熱を逃がす。夜行性。淡い色の毛が光を反射する。</li></ul><p><strong>熱帯雨林</strong>（問題: 光をめぐる激しい競争、絶え間ない大雨、多くの捕食者や草食動物）</p><ul><li>多くの樹木は<em>板根 (buttress roots)</em> をもち、薄い土壌で浅い根の高い幹を支える。</li><li>多くの葉に<em>ドリップチップ (drip tip)</em> があり、水をすばやく落とす。</li><li><em>ラン (orchids)</em>（植物）は枝の上に着生し（着生植物）、気根で林冠の高い所の光に届く。</li><li><em>アカメアマガエル (red-eyed tree frog)</em>（動物）: 登るための粘着性の指先パッド。緑色が葉の間で保護色になる。</li><li><em>ミユビナマケモノ (three-toed sloth)</em>（動物）: ぶら下がるための強い曲がった爪。動きが遅くエネルギー需要が低い。毛に生える藻類で緑がかり、保護色になる。</li></ul>",
        "<p>你需要為兩種生物群系各舉出植物和動物<strong>有名稱的物種</strong>的適應例子。</p><p><strong>熱帶沙漠</strong>（難題：水極少、極熱）：</p><ul><li><em>巨人柱仙人掌 (saguaro cactus)</em>（植物）：肥厚多肉的莖儲水；葉退化成刺，減少失水並阻嚇草食動物；淺而廣闊的根能迅速吸收短暫的雨水。</li><li><em>單峰駱駝 (dromedary camel)</em>（動物）：能耐受大量失水；排出濃縮的尿液和乾燥的糞便；駝峰儲存的是脂肪（不是水）；日間容許體溫上升，減少出汗。</li><li><em>更格盧鼠 (kangaroo rat)</em>（動物）：日間躲在洞穴、夜間活動，避開炎熱；尿液極濃；大部分水分來自食物和呼吸作用。</li><li><em>大耳狐 (fennec fox)</em>（動物）：多血管的大耳散熱；夜間活動；淺色毛皮反射光線。</li></ul><p><strong>熱帶雨林</strong>（難題：激烈爭光、持續大雨、眾多捕食者和草食動物）：</p><ul><li>許多樹木有<em>板根 (buttress roots)</em>，在薄土中支撐高大而根淺的樹幹。</li><li>許多葉片有<em>滴水尖 (drip tip)</em>，幫助迅速排走水分。</li><li><em>蘭花 (orchids)</em>（植物）以附生植物形式長在樹枝上，靠氣生根，在樹冠高處獲取光線。</li><li><em>紅眼樹蛙 (red-eyed tree frog)</em>（動物）：有黏性趾墊以便攀爬；綠色在葉間作保護色。</li><li><em>三趾樹懶 (three-toed sloth)</em>（動物）：有強而彎曲的爪以便懸掛；動作緩慢，能量需求低；毛上的藻類使其帶綠色，成為保護色。</li></ul>"
      ),
      examTip: L("Always name the species, state the adaptation and say how it helps with the problem (water, heat, light). Choose one plant and one animal for each biome.", "必ず種名を挙げ、適応を述べ、問題（水、熱、光）にどう役立つかを説明します。各バイオームで植物と動物を1つずつ選びましょう。", "必須寫出物種名稱，說明適應特徵，並說明它如何應付難題（水、熱、光）。每種生物群系各選一種植物和一種動物。")
    }
  ],
  keyTerms: [
    { ahl: false, term: L("habitat", "生息地", "生境"), def: L("The place where a community, species, population or organism lives.", "群集、種、個体群、個体が生活する場所。", "群落、物種、種群或生物生活的地方。") },
    { ahl: false, term: L("abiotic factor", "非生物的要因", "非生物因素"), def: L("A non-living part of the environment, such as temperature, light, water, pH or salinity.", "温度、光、水、pH、塩分など、環境のうち生物でない部分。", "環境中沒有生命的部分，如溫度、光、水、pH或鹽度。") },
    { ahl: false, term: L("range of tolerance", "耐性の範囲", "耐受範圍"), def: L("The span of values of an abiotic variable within which a species can survive.", "種が生存できる非生物的変数の値の幅。", "物種能存活的非生物變量數值範圍。") },
    { ahl: false, term: L("limiting factor", "制限要因", "限制因素"), def: L("A variable whose value is near or beyond the edge of a species' range of tolerance, so it restricts where the species lives or how well it grows.", "値が種の耐性の範囲の端に近い（または外にある）ため、種の生息場所や成長を制限する変数。", "數值接近或超出物種耐受範圍邊緣，因而限制物種分佈或生長的變量。") },
    { ahl: false, term: L("transect", "トランセクト（調査線）", "樣帶"), def: L("A line across a habitat along which organisms and abiotic variables are recorded.", "生息地を横切る線で、これに沿って生物と非生物的変数を記録する。", "橫過生境的一條線，沿線記錄生物和非生物變量。") },
    { ahl: false, term: L("biome", "バイオーム", "生物群系"), def: L("A group of ecosystems with similar communities because of similar abiotic conditions.", "似た非生物的条件のため似た群集をもつ生態系のまとまり。", "因非生物條件相似而擁有相似群落的一組生態系統。") },
    { ahl: false, term: L("convergent evolution", "収れん進化", "趨同演化"), def: L("The independent evolution of similar adaptations in unrelated species facing similar selection pressures.", "似た選択圧に直面した類縁のない種で、似た適応が独立に進化すること。", "親緣關係疏遠的物種因面對相似選擇壓力而獨立演化出相似適應特徵。") },
    { ahl: false, term: L("coral reef", "サンゴ礁", "珊瑚礁"), def: L("A marine ecosystem built by corals from calcium carbonate skeletons, needing warm, clear, shallow, salty, alkaline water.", "サンゴが炭酸カルシウムの骨格でつくる海洋生態系。暖かく澄んだ浅い塩分のある弱アルカリ性の水を必要とする。", "由珊瑚以碳酸鈣骨骼建成的海洋生態系統，需要溫暖、清澈、淺而鹹的微鹼性海水。") }
  ],
  misconceptions: [
    { wrong: L("Habitat and niche mean the same thing.", "生息地とニッチは同じ意味である。", "生境與生態位意思相同。"), right: L("Habitat is where an organism lives. Niche is its role in the ecosystem.", "生息地は生物が住む場所、ニッチは生態系での役割。", "生境是生物居住的地方；生態位是它在生態系統中的角色。") },
    { wrong: L("A species can live anywhere in the world if it is given enough food.", "十分な食物があれば、種は世界のどこでも生きられる。", "只要有足夠食物，物種可在世界任何地方生存。"), right: L("Every species has a range of tolerance for each abiotic factor. Outside it, the species cannot survive, whatever the food supply.", "どの種も各非生物的要因に耐性の範囲があり、その外では食物があっても生存できない。", "每個物種對各非生物因素都有耐受範圍，超出範圍便不能存活，無論食物供應多少。") },
    { wrong: L("Camels store water in their humps.", "ラクダはこぶに水をためている。", "駱駝在駝峰中儲水。"), right: L("The hump stores fat. Camels survive by tolerating water loss and producing concentrated urine.", "こぶにたくわえているのは脂肪。ラクダは水分の損失に耐え、濃い尿をつくることで生き延びる。", "駝峰儲存的是脂肪。駱駝靠耐受失水和排出濃縮尿液生存。") },
    { wrong: L("Similar-looking organisms on different continents must be closely related.", "別々の大陸で似た姿の生物は近縁に違いない。", "不同大陸上外貌相似的生物必然親緣關係密切。"), right: L("They are often unrelated and have evolved similar adaptations independently (convergent evolution) because of similar abiotic conditions.", "多くは類縁がなく、似た非生物的条件のために似た適応を独立に進化させた（収れん進化）。", "它們往往沒有親緣關係，只是因非生物條件相似而獨立演化出相似適應特徵（趨同演化）。") }
  ],
  beyondSyllabus: [
    L("You do not need to name particular biomes beyond the six listed (tropical forest, temperate forest, taiga, grassland, tundra, hot desert), or the exact boundaries on a Whittaker diagram.", "挙げられた6つ（熱帯林、温帯林、タイガ、草原、ツンドラ、熱帯砂漠）以外のバイオームや、ホイッタカー図の正確な境界は不要です。", "你不需要認識六種（熱帶森林、溫帶森林、針葉林、草原、苔原、熱帶沙漠）以外的生物群系，或惠特克圖的確切界線。"),
    L("You do not need to know exact temperature, rainfall or pH values for biomes or coral reefs; general conditions are enough.", "バイオームやサンゴ礁の正確な温度、降水量、pHの値は不要で、一般的な条件で十分です。", "你不需要記住生物群系或珊瑚礁的確切溫度、雨量或pH值；掌握一般條件便足夠。"),
    L("Spearman's rank correlation is not named anywhere in the guide, so you do not need to learn its formula. However, the guide's skills section (Tools: mathematics) expects you to interpret a correlation coefficient (r) as positive or negative and to use R² to judge the fit of a trend line, so you may be given an r value for transect data and asked what it means.", "スピアマンの順位相関はガイドのどこにも出てこないので、その式を覚える必要はありません。ただしガイドの技能の節（ツール: 数学）では、相関係数 (r) を正・負として解釈し、R² で傾向線の当てはまりを判断することが求められます。トランセクトのデータについて r の値が与えられ、その意味を問われることはありえます。", "課程指引中沒有提及斯皮爾曼等級相關 (Spearman's rank)，所以你不需要學它的公式。不過，指引的技能部分（工具：數學）要求你解讀相關係數 (r) 的正負，並用 R² 判斷趨勢線的擬合程度，所以題目可能給出樣帶數據的 r 值並問你其意思。"),
    L("You do not need the details of CAM or C4 photosynthesis as adaptations of desert plants.", "砂漠植物の適応としてのCAMやC4光合成の詳細は不要です。", "你不需要掌握CAM或C4光合作用作為沙漠植物適應特徵的細節。"),
    L("Not needed for this subtopic: threats to coral reefs (ocean acidification from rising carbon dioxide suppressing calcification, and bleaching caused by rising water temperature). These are taught in D4.3 (Climate change, SL and HL). Here you only need the conditions for reef formation.", "この小テーマでは不要: サンゴ礁への脅威（二酸化炭素の増加による海洋酸性化が石灰化を妨げること、水温上昇による白化）。これらは D4.3 (気候変動, SL・HL 共通) で学びます。ここではサンゴ礁形成の条件だけが必要です。", "此子課題不需要：珊瑚礁面對的威脅（二氧化碳增加引致海洋酸化，抑制珊瑚鈣化；水溫上升引致珊瑚白化）。這些會在 D4.3 (氣候變化，SL 及 HL) 學習。這裏只需掌握珊瑚礁形成的條件。"),
    L("You do not need to name more than the examples you choose; the guide asks for a grass of sand dunes, a tree of mangrove swamps and named plants and animals of hot deserts and tropical rainforest.", "選んだ例以上の種名は不要です。指針が求めるのは、砂丘の草、マングローブ湿地の樹木、熱帯砂漠と熱帯雨林の名前のある植物・動物です。", "你只需掌握自己選用的例子；指引要求沙丘的一種草、紅樹林沼澤的一種樹，以及熱帶沙漠與熱帶雨林中有名稱的動植物。")
  ],
  links: [
    { to: "B4.2", why: L("A species' niche depends on its adaptations and tolerance limits, and competition narrows its realized niche.", "種のニッチは適応と耐性の限界によって決まり、競争が実現ニッチを狭める。", "物種的生態位取決於其適應特徵和耐受極限，而競爭會縮窄其實現生態位。") },
    { to: "A4.1", why: L("Adaptations arise by natural selection; convergent evolution gives similar adaptations in unrelated species.", "適応は自然選択で生じ、収れん進化が類縁のない種に似た適応をもたらす。", "適應特徵經自然選擇產生；趨同演化令不相關物種有相似的適應特徵。") },
    { to: "B3.1", why: L("Gas exchange adaptations (for example mangrove breathing roots) link to the need to exchange gases.", "ガス交換の適応（例: マングローブの呼吸根）は、ガス交換の必要性とつながる。", "氣體交換的適應（例如紅樹的呼吸根）與氣體交換的需要相連。") }
  ],
  natureOfScience: [
    L("Fieldwork and sampling: random and systematic sampling along a transect, with abiotic sensors, give quantitative evidence for the link between distribution and the environment.", "野外調査とサンプリング: トランセクトに沿ったランダム／系統的サンプリングと非生物的センサーが、分布と環境の関係についての定量的な証拠を与える。", "野外工作與抽樣：沿樣帶進行隨機和系統抽樣，加上非生物感應器，為分佈與環境之間的關係提供量化證據。")
  ],
  questions: [
    { id: "b4-1-q01", type: "mcq", ahl: false, difficulty: 1, ref: "B4.1.1", paper: "1A",
      stem: L("Which statement best defines a habitat?", "生息地を最もよく定義しているのはどれか。", "哪項敘述最能定義生境？"),
      options: [L("The role of a species in an ecosystem", "生態系での種の役割", "物種在生態系統中的角色"), L("The place where an organism, population or community lives", "生物、個体群、群集が生活する場所", "生物、種群或群落生活的地方"), L("All the organisms of one species in an area", "ある地域の1種のすべての生物", "某地區內同一物種的所有生物"), L("The range of temperatures a species can tolerate", "種が耐えられる温度の範囲", "物種能耐受的溫度範圍")],
      answer: 1,
      explanation: L("A habitat is where organisms live. Option A is the definition of a niche, a very common mix-up. Option C describes a population. Option D describes a range of tolerance.", "生息地は生物が住む場所です。Aはニッチの定義で、よくある混同です。Cは個体群、Dは耐性の範囲です。", "生境是生物居住的地方。A是生態位的定義，是很常見的混淆。C描述種群，D描述耐受範圍。") },
    { id: "b4-1-q02", type: "mcq", ahl: false, difficulty: 2, ref: "B4.1.2", paper: "1A",
      stem: L("Marram grass has leaves that roll up, with the stomata on the inside. How does this help it live on sand dunes?", "マラムグラスは気孔を内側にして葉を巻く。これは砂丘での生活にどう役立つか。", "濱草的葉片捲起，氣孔在內側。這如何幫助它在沙丘生活？"),
      options: [L("It traps humid air and reduces water loss by transpiration.", "湿った空気をためて蒸散による水分損失を減らす。", "困住濕潤空氣，減少蒸騰失水。"), L("It increases the surface area for absorbing light.", "光を吸収する表面積を増やす。", "增加吸收光線的表面積。"), L("It allows the leaves to absorb salt water.", "葉が塩水を吸収できるようになる。", "讓葉片吸收鹹水。"), L("It stops the roots from growing deeper.", "根が深く伸びるのを防ぐ。", "阻止根向深處生長。")],
      answer: 0,
      explanation: L("Rolling the leaf traps a humid layer around the stomata, so the water-vapour gradient is smaller and less water is lost. Option B is the opposite: rolling reduces exposed surface. The other options have no link to leaf rolling.", "葉を巻くと気孔の周りに湿った層ができ、水蒸気の濃度勾配が小さくなって水分損失が減ります。Bは逆で、巻くと露出面積は減ります。他の選択肢は葉を巻くこととは無関係です。", "捲葉在氣孔周圍形成濕潤層，水蒸氣梯度變小，失水減少。B相反，捲葉會減少外露表面積。其他選項與捲葉無關。") },
    { id: "b4-1-q03", type: "mcq", ahl: false, difficulty: 2, ref: "B4.1.2", paper: "1A",
      stem: L("Why do many mangrove trees have roots that grow up out of the mud?", "多くのマングローブの樹木が泥から上に出る根をもつのはなぜか。", "為何許多紅樹有長出泥面的根？"),
      options: [L("To absorb more mineral ions from the mud", "泥からより多くの無機イオンを吸収するため", "從泥中吸收更多礦物離子"), L("To allow gas exchange where the mud contains little oxygen", "泥に酸素が少ない所でガス交換するため", "在泥中缺氧的地方進行氣體交換"), L("To store fresh water for dry periods", "乾期のために淡水をためるため", "為乾旱期儲存淡水"), L("To reach light under the water", "水中の光に届くため", "在水下獲取光線")],
      answer: 1,
      explanation: L("Waterlogged mud is low in oxygen, so roots that rise above it allow gas exchange. Absorbing minerals would be done by roots in the mud, not those above it. Mangroves live in salt water, so they do not store fresh water in roots.", "水浸しの泥は酸素が乏しいため、泥の上に出た根でガス交換を行います。無機イオンの吸収は泥の中の根が行います。マングローブは塩水に住み、根に淡水をためることはしません。", "積水的泥缺氧，所以伸出泥面的根可進行氣體交換。吸收礦物是由泥中的根負責。紅樹生活在鹹水中，並不在根中儲存淡水。") },
    { id: "b4-1-q04", type: "multi", ahl: false, difficulty: 1, ref: "B4.1.3", paper: "1A",
      stem: L("Select ALL the abiotic variables.", "非生物的変数をすべて選べ。", "選出所有非生物變量。"),
      options: [L("Soil pH", "土壌のpH", "土壤pH"), L("Light intensity", "光の強さ", "光強度"), L("Number of predators", "捕食者の数", "捕食者數目"), L("Temperature", "温度", "溫度"), L("Presence of a competing species", "競争する種の存在", "有競爭物種存在")],
      answer: [0, 1, 3],
      explanation: L("Soil pH, light and temperature are non-living. Predators and competitors are living organisms, so they are biotic factors.", "土壌のpH、光、温度は生物でない要因です。捕食者や競争種は生物なので生物的要因です。", "土壤pH、光和溫度屬非生物。捕食者和競爭物種是生物，屬生物因素。") },
    { id: "b4-1-q05", type: "match", ahl: false, difficulty: 2, ref: "B4.1.8", paper: "1A",
      stem: L("Match each species with an adaptation to its habitat.", "各種を、生息地への適応と対応させよ。", "把各物種與其適應特徵配對。"),
      pairs: [
        { left: L("Saguaro cactus", "サワロサボテン", "巨人柱仙人掌"), right: L("Fleshy stem stores water; leaves reduced to spines", "多肉質の茎が水をたくわえる。葉はトゲに退化", "多肉的莖儲水；葉退化成刺") },
        { left: L("Kangaroo rat", "カンガルーネズミ", "更格盧鼠"), right: L("Nocturnal, makes very concentrated urine", "夜行性で、非常に濃い尿をつくる", "夜間活動，排出極濃的尿液") },
        { left: L("Orchid on a rainforest branch", "熱帯雨林の枝上のラン", "雨林樹枝上的蘭花"), right: L("Epiphyte with aerial roots, reaching light in the canopy", "気根をもつ着生植物で、林冠の光に届く", "有氣生根的附生植物，在樹冠獲得光線") },
        { left: L("Red-eyed tree frog", "アカメアマガエル", "紅眼樹蛙"), right: L("Sticky toe pads for climbing; green camouflage", "登るための粘着性の指先パッド。緑の保護色", "有黏性趾墊以攀爬；綠色保護色") }
      ],
      explanation: L("Each adaptation solves a problem of its habitat: water shortage in deserts, or climbing and light competition in rainforest.", "各適応は生息地の問題を解決します。砂漠では水不足、熱帯雨林では登ることと光をめぐる競争です。", "每項適應都解決生境的難題：沙漠缺水，雨林則是攀爬和爭光。") },
    { id: "b4-1-q06", type: "order", ahl: false, difficulty: 1, ref: "B4.1.4", paper: "1A",
      stem: L("Put the steps of a transect survey in a sensible order.", "トランセクト調査の手順を適切な順に並べよ。", "把樣帶調查的步驟排成合理次序。"),
      items: [L("Lay a measuring tape across the habitat", "メジャーを生息地に張る", "橫過生境拉一條捲尺"), L("Place a quadrat at the first sampling point", "最初の調査地点にコドラートを置く", "在第一個取樣點放置樣方"), L("Record the species abundance or percentage cover and measure an abiotic variable at the same point", "同じ地点で、コドラート内の種の個体数または被度を記録し、非生物的変数を測定する", "在同一點記錄樣方內物種的數量或覆蓋百分率，並量度一個非生物變量"), L("Repeat at each interval along the tape", "メジャーに沿って各間隔で繰り返す", "沿捲尺每隔一段重複"), L("Graph the data and look for a correlation", "データをグラフにして相関を探す", "把數據繪圖並尋找相關性")],
      explanation: L("You set up the line, sample at each point (both biotic and abiotic data from the same place), then analyse.", "線を設定し、各地点で（同じ場所から生物と非生物のデータを）調べ、その後分析します。", "先設定樣帶線，在每一點取樣（同一地點的生物和非生物數據），然後分析。") },
    { id: "b4-1-q07", type: "short", ahl: false, difficulty: 2, ref: "B4.1.2", paper: "2", commandTerm: "Outline", marks: 3,
      stem: L("Outline three adaptations of mangrove trees to life in a mangrove swamp.", "マングローブ湿地での生活に対するマングローブの樹木の適応を3つ概説せよ。", "概述紅樹對紅樹林沼澤生活的三項適應。"),
      markscheme: [L("Roots growing above the mud (aerial/breathing roots) allow gas exchange in oxygen-poor, waterlogged mud", "泥の上に出る根（気根・呼吸根）が、酸素の乏しい水浸しの泥でのガス交換を可能にする", "伸出泥面的根（氣生根／呼吸根）讓樹木在缺氧積水的泥中進行氣體交換"), L("Salt excluded by roots or secreted from leaves so the tree can cope with salt water", "根で塩分を排除するか葉から排出し、塩水に対処できる", "根部排除鹽分或葉片排出鹽分，使樹木能應付鹹水"), L("Prop roots support the tree in soft, unstable mud", "支柱根が柔らかく不安定な泥の中で樹木を支える", "支持根在軟而不穩的泥中支撐樹木"), L("Seeds germinate on the tree (e.g. Rhizophora); seedlings drop into mud and root quickly", "種子が樹上で発芽する（例: Rhizophora）。芽生えが泥に落ちて素早く根づく", "種子在樹上萌發（如Rhizophora）；幼苗掉入泥中迅速生根")],
      modelAnswer: L("Aerial roots let the tree exchange gases in oxygen-poor mud. Salt is excluded at the roots or secreted from the leaves. Prop roots support the tree in soft mud.", "気根により、酸素の乏しい泥の中でもガス交換できます。塩分は根で排除されるか葉から排出されます。支柱根が柔らかい泥の中で樹木を支えます。", "氣生根令樹木能在缺氧的泥中進行氣體交換；鹽分在根部被排除或由葉片排出；支持根在軟泥中支撐樹木。") },
    { id: "b4-1-q08", type: "short", ahl: false, difficulty: 2, ref: "B4.1.4", paper: "1B", commandTerm: "Describe", marks: 4,
      stem: L("A transect was run from the sea inland across a sand dune system. (a) Describe the relationship between sand moisture and the percentage cover of the plant species (2 marks). (b) Suggest one reason why the plant species is absent close to the sea (1 mark). (c) Suggest one way to improve the reliability of the data (1 mark).", "海から内陸へ砂丘を横切るトランセクトを行った。(a) 砂の水分と植物種の被度（％）の関係を述べよ（2点）。(b) 海の近くにその植物種がいない理由を1つ推論せよ（1点）。(c) データの信頼性を高める方法を1つ挙げよ（1点）。", "沿沙丘系統由海邊向內陸進行了樣帶調查。(a) 描述沙的水分與該植物物種覆蓋百分率的關係（2分）。(b) 提出該植物在近海處缺席的一個原因（1分）。(c) 提出一個提高數據可靠性的方法（1分）。"),
      data: L("<p>(illustrative data)</p><table><tr><th>Distance from sea (m)</th><th>Sand moisture (%)</th><th>Cover of plant species (%)</th></tr><tr><td>0</td><td>1</td><td>0</td></tr><tr><td>10</td><td>2</td><td>5</td></tr><tr><td>20</td><td>4</td><td>20</td></tr><tr><td>30</td><td>6</td><td>40</td></tr><tr><td>40</td><td>9</td><td>65</td></tr><tr><td>50</td><td>12</td><td>80</td></tr></table>", "<p>（説明用データ）</p><table><tr><th>海からの距離 (m)</th><th>砂の水分 (%)</th><th>植物種の被度 (%)</th></tr><tr><td>0</td><td>1</td><td>0</td></tr><tr><td>10</td><td>2</td><td>5</td></tr><tr><td>20</td><td>4</td><td>20</td></tr><tr><td>30</td><td>6</td><td>40</td></tr><tr><td>40</td><td>9</td><td>65</td></tr><tr><td>50</td><td>12</td><td>80</td></tr></table>", "<p>（示意數據）</p><table><tr><th>離海距離 (m)</th><th>沙的水分 (%)</th><th>植物覆蓋 (%)</th></tr><tr><td>0</td><td>1</td><td>0</td></tr><tr><td>10</td><td>2</td><td>5</td></tr><tr><td>20</td><td>4</td><td>20</td></tr><tr><td>30</td><td>6</td><td>40</td></tr><tr><td>40</td><td>9</td><td>65</td></tr><tr><td>50</td><td>12</td><td>80</td></tr></table>"),
      markscheme: [L("(a) Positive correlation: as sand moisture increases, percentage cover increases", "(a) 正の相関: 砂の水分が増えると被度も増える", "(a) 正相關：沙的水分增加，覆蓋百分率也增加"), L("(a) Quoting data, e.g. cover rises from 0 % at 1 % moisture to 80 % at 12 % moisture", "(a) データの引用（例: 水分1 %で被度0 %、水分12 %で被度80 %）", "(a) 引用數據（如水分1 %時覆蓋0 %，水分12 %時覆蓋80 %）"), L("(b) Sand is too dry (low moisture), or too salty / too much wind or salt spray, outside the species' range of tolerance", "(b) 砂が乾燥しすぎている、または塩分・風・潮しぶきが多く、種の耐性の範囲外", "(b) 沙太乾，或太鹹／風大／浪花飛沫多，超出該物種的耐受範圍"), L("(c) Repeat the transect / use more quadrats at each point and calculate the mean (accept: sample at random positions along several parallel transects)", "(c) トランセクトを繰り返す／各地点でコドラートを増やして平均を求める（複数の平行なトランセクトも可）", "(c) 重複樣帶調查／每點使用更多樣方並計算平均值（沿多條平行樣帶隨機取樣亦可）")],
      modelAnswer: L("(a) There is a positive correlation: as sand moisture rises from 1 % to 12 %, cover rises from 0 % to 80 %. (b) The sand near the sea is too dry or salty for the species. (c) Repeat the transect several times and use the mean.", "(a) 正の相関があり、砂の水分が1 %から12 %に上がると被度は0 %から80 %に上がる。(b) 海の近くの砂は乾燥しすぎか塩分が高すぎる。(c) トランセクトを何度か繰り返し、平均を使う。", "(a) 呈正相關：沙的水分由1 %升至12 %，覆蓋由0 %升至80 %。(b) 近海的沙太乾或太鹹，該物種不能生存。(c) 重複樣帶調查數次並取平均值。") },
    { id: "b4-1-q09", type: "short", ahl: false, difficulty: 3, ref: "B4.1.3", paper: "1B", commandTerm: "Deduce", marks: 4,
      stem: L("The table shows survival of two fish species after four weeks at different water temperatures (illustrative data). (a) State the optimum temperature for each species (1 mark). (b) Compare the ranges of tolerance of the two species (2 marks). (c) Deduce which species is more likely to live in a stream fed by melting snow (1 mark).", "表は、異なる水温で4週間後の2種の魚の生存率（説明用データ）である。(a) 各種の最適温度を述べよ（1点）。(b) 2種の耐性の範囲を比較せよ（2点）。(c) 雪解け水が流れ込む小川に住む可能性が高いのはどちらの種か推論せよ（1点）。", "下表顯示兩種魚在不同水溫下四星期後的存活率（示意數據）。(a) 寫出各物種的最適溫度（1分）。(b) 比較兩物種的耐受範圍（2分）。(c) 推斷哪個物種較可能生活在由融雪補給的溪流中（1分）。"),
      data: L("<table><tr><th>Temperature (°C)</th><th>Species P survival (%)</th><th>Species Q survival (%)</th></tr><tr><td>5</td><td>0</td><td>50</td></tr><tr><td>10</td><td>40</td><td>100</td></tr><tr><td>15</td><td>90</td><td>90</td></tr><tr><td>20</td><td>100</td><td>30</td></tr><tr><td>25</td><td>85</td><td>0</td></tr><tr><td>30</td><td>0</td><td>0</td></tr></table>", "<table><tr><th>温度 (°C)</th><th>種Pの生存率 (%)</th><th>種Qの生存率 (%)</th></tr><tr><td>5</td><td>0</td><td>50</td></tr><tr><td>10</td><td>40</td><td>100</td></tr><tr><td>15</td><td>90</td><td>90</td></tr><tr><td>20</td><td>100</td><td>30</td></tr><tr><td>25</td><td>85</td><td>0</td></tr><tr><td>30</td><td>0</td><td>0</td></tr></table>", "<table><tr><th>溫度 (°C)</th><th>物種P存活率 (%)</th><th>物種Q存活率 (%)</th></tr><tr><td>5</td><td>0</td><td>50</td></tr><tr><td>10</td><td>40</td><td>100</td></tr><tr><td>15</td><td>90</td><td>90</td></tr><tr><td>20</td><td>100</td><td>30</td></tr><tr><td>25</td><td>85</td><td>0</td></tr><tr><td>30</td><td>0</td><td>0</td></tr></table>"),
      markscheme: [L("(a) P: 20 °C; Q: 10 °C", "(a) P: 20 °C、Q: 10 °C", "(a) P：20 °C；Q：10 °C"), L("(b) P survives at about 10–25 °C and Q at about 5–20 °C (accept: ranges overlap at 10–20 °C)", "(b) Pはおよそ10〜25 °C、Qはおよそ5〜20 °Cで生存する（10〜20 °Cで重なる）", "(b) P約在10–25 °C存活，Q約在5–20 °C存活（兩者在10–20 °C重疊）"), L("(b) Q tolerates colder water, P tolerates warmer water (accept: neither survives at 30 °C; only Q survives at 5 °C)", "(b) Qはより冷たい水に、Pはより暖かい水に耐える（30 °Cではどちらも生存しない。5 °Cで生存するのはQのみ）", "(b) Q耐較冷的水，P耐較暖的水（30 °C時兩者皆不能存活；5 °C時只有Q存活）"), L("(c) Species Q, because it survives at low temperatures (100 % at 10 °C, 50 % at 5 °C)", "(c) 種Q。低温で生存できる（10 °Cで100 %、5 °Cで50 %）ため", "(c) 物種Q，因為它能在低溫存活（10 °C時100 %，5 °C時50 %）")],
      modelAnswer: L("(a) P 20 °C, Q 10 °C. (b) P tolerates about 10–25 °C and Q about 5–20 °C, so Q tolerates colder water and P warmer water; the ranges overlap between 10 and 20 °C. (c) Q, because it survives at low temperature.", "(a) P 20 °C、Q 10 °C。(b) Pはおよそ10〜25 °C、Qはおよそ5〜20 °Cに耐えるので、Qはより冷たい水に、Pはより暖かい水に耐える。範囲は10〜20 °Cで重なる。(c) Q。低温で生存できるため。", "(a) P 20 °C，Q 10 °C。(b) P耐受約10–25 °C，Q約5–20 °C，所以Q耐較冷的水，P耐較暖的水；兩者範圍在10至20 °C重疊。(c) Q，因其能在低溫存活。") },
    { id: "b4-1-q10", type: "short", ahl: false, difficulty: 2, ref: "B4.1.6", paper: "1B", commandTerm: "Deduce", marks: 3,
      stem: L("Using the biome graph in section B4.1.6, deduce the most likely biome at each site (illustrative data): site X, 27 °C and 2800 mm rainfall; site Y, −8 °C and 200 mm; site Z, 28 °C and 100 mm.", "B4.1.6のバイオーム図を使い、各地点で最も可能性の高いバイオームを推論せよ（説明用データ）: 地点X 27 °C・降水量2800 mm、地点Y −8 °C・200 mm、地点Z 28 °C・100 mm。", "利用B4.1.6的生物群系圖，推斷各地點最可能的生物群系（示意數據）：地點X 27 °C、雨量2800 mm；地點Y −8 °C、200 mm；地點Z 28 °C、100 mm。"),
      markscheme: [L("X: tropical forest (hot and very wet)", "X: 熱帯林（高温で非常に多雨）", "X：熱帶森林（炎熱且極濕）"), L("Y: tundra (very cold, low rainfall)", "Y: ツンドラ（非常に寒く降水が少ない）", "Y：苔原（極寒，雨量少）"), L("Z: hot desert (hot, very low rainfall)", "Z: 熱帯砂漠（高温で降水が非常に少ない）", "Z：熱帶沙漠（炎熱，雨量極低）")],
      modelAnswer: L("X is tropical forest, Y is tundra and Z is hot desert.", "Xは熱帯林、Yはツンドラ、Zは熱帯砂漠。", "X是熱帶森林，Y是苔原，Z是熱帶沙漠。") },
    { id: "b4-1-q11", type: "mcq", ahl: false, difficulty: 2, ref: "B4.1.5", paper: "1B",
      stem: L("The table shows four sites (illustrative data). Which site is most likely to support coral reef formation?", "表は4つの地点を示す（説明用データ）。サンゴ礁が形成される可能性が最も高い地点はどれか。", "下表顯示四個地點（示意數據）。哪個地點最可能形成珊瑚礁？"),
      data: L("<table><tr><th>Site</th><th>Depth (m)</th><th>Temperature (°C)</th><th>Salinity (parts per thousand)</th><th>Water clarity</th></tr><tr><td>1</td><td>8</td><td>27</td><td>35</td><td>Clear</td></tr><tr><td>2</td><td>8</td><td>27</td><td>18</td><td>Cloudy (river mouth)</td></tr><tr><td>3</td><td>70</td><td>25</td><td>35</td><td>Clear</td></tr><tr><td>4</td><td>6</td><td>12</td><td>35</td><td>Clear</td></tr></table>", "<table><tr><th>地点</th><th>水深 (m)</th><th>温度 (°C)</th><th>塩分 (千分率)</th><th>透明度</th></tr><tr><td>1</td><td>8</td><td>27</td><td>35</td><td>澄んでいる</td></tr><tr><td>2</td><td>8</td><td>27</td><td>18</td><td>濁っている（河口）</td></tr><tr><td>3</td><td>70</td><td>25</td><td>35</td><td>澄んでいる</td></tr><tr><td>4</td><td>6</td><td>12</td><td>35</td><td>澄んでいる</td></tr></table>", "<table><tr><th>地點</th><th>水深 (m)</th><th>溫度 (°C)</th><th>鹽度（千分率）</th><th>清澈度</th></tr><tr><td>1</td><td>8</td><td>27</td><td>35</td><td>清澈</td></tr><tr><td>2</td><td>8</td><td>27</td><td>18</td><td>混濁（河口）</td></tr><tr><td>3</td><td>70</td><td>25</td><td>35</td><td>清澈</td></tr><tr><td>4</td><td>6</td><td>12</td><td>35</td><td>清澈</td></tr></table>"),
      options: [L("Site 1", "地点1", "地點1"), L("Site 2", "地点2", "地點2"), L("Site 3", "地点3", "地點3"), L("Site 4", "地点4", "地點4")],
      answer: 0,
      explanation: L("Site 1 is shallow, warm, of normal salinity and clear. Site 2 has low salinity and cloudy water. Site 3 is too deep for enough light to reach the coral's algae. Site 4 is too cold.", "地点1は浅く、暖かく、塩分が通常で、澄んでいます。地点2は塩分が低く濁っています。地点3は深すぎてサンゴの藻類に十分な光が届きません。地点4は冷たすぎます。", "地點1水淺、溫暖、鹽度正常且清澈。地點2鹽度低而混濁。地點3太深，光線不足以到達珊瑚的藻類。地點4太冷。") },
    { id: "b4-1-q12", type: "multi", ahl: false, difficulty: 2, ref: "B4.1.5", paper: "1A",
      stem: L("Select ALL the conditions that favour the formation of a coral reef.", "サンゴ礁の形成に有利な条件をすべて選べ。", "選出所有有利珊瑚礁形成的條件。"),
      options: [L("Shallow water", "浅い水", "淺水"), L("Clear water", "澄んだ水", "清澈的水"), L("Warm temperature", "暖かい水温", "溫暖的水溫"), L("Low salinity", "低い塩分", "低鹽度"), L("Acidic sea water", "酸性の海水", "酸性海水")],
      answer: [0, 1, 2],
      explanation: L("Reef corals need light (shallow, clear water) and warmth. Low salinity stresses them, and acidic water makes the calcium carbonate skeleton dissolve, so these two do not favour reefs.", "造礁サンゴは光（浅く澄んだ水）と暖かさが必要です。低塩分はストレスになり、酸性の水は炭酸カルシウムの骨格を溶かすので、この2つは不利です。", "造礁珊瑚需要光（淺而清澈的水）和溫暖。低鹽度令珊瑚受壓，酸性水會令碳酸鈣骨骼溶解，所以這兩項不利珊瑚礁形成。") },
    { id: "b4-1-q13", type: "mcq", ahl: false, difficulty: 2, ref: "B4.1.7", paper: "1A",
      stem: L("Why do hot deserts on different continents contain plants with similar spiny, water-storing stems even though the plants are not closely related?", "異なる大陸の熱帯砂漠に、近縁でない植物が似たトゲのある貯水茎をもつのはなぜか。", "為何不同大陸的熱帶沙漠中，親緣關係疏遠的植物有相似的帶刺、儲水的莖？"),
      options: [L("They share a recent common ancestor.", "最近の共通祖先を共有しているから。", "它們有最近的共同祖先。"), L("Convergent evolution under similar abiotic conditions", "似た非生物的条件下での収れん進化", "在相似非生物條件下的趨同演化"), L("The deserts are connected by land bridges.", "砂漠が陸橋でつながっているから。", "沙漠之間有陸橋相連。"), L("Plants acquire the adaptations they need during their own lifetime.", "植物は必要な適応を生きている間に獲得するから。", "植物在一生中獲得所需的適應特徵。")],
      answer: 1,
      explanation: L("Similar selection pressures (dryness, heat, herbivores) favoured similar features independently: convergent evolution. A recent common ancestor would give homology, which is not the case here. Individuals do not acquire adaptations during life; they are inherited.", "似た選択圧（乾燥、暑さ、草食動物）が独立に似た特徴を有利にしました。これが収れん進化です。最近の共通祖先なら相同になりますが、ここでは当てはまりません。適応は遺伝するもので、個体が生きている間に獲得するものではありません。", "相似的選擇壓力（乾旱、炎熱、草食動物）獨立地選擇出相似特徵，這就是趨同演化。若有最近共同祖先，則屬同源，但此處並非如此。適應特徵是遺傳的，並非個體一生中獲得。") },
    { id: "b4-1-q14", type: "short", ahl: false, difficulty: 3, ref: "B4.1.7", paper: "2", commandTerm: "Explain", marks: 3,
      stem: L("Explain why tropical rainforests in South America, Africa and South-East Asia look similar although most of their species are different.", "南米、アフリカ、東南アジアの熱帯雨林は、種の大半が異なるのに似て見えるのはなぜか説明せよ。", "解釋為何南美洲、非洲和東南亞的熱帶雨林外貌相似，但大部分物種不同。"),
      markscheme: [L("All have similar abiotic conditions (hot, very wet all year)", "どれも似た非生物的条件（一年中高温で多雨）をもつ", "它們都有相似的非生物條件（全年炎熱多雨）"), L("This leads to similar selection pressures (e.g. competition for light, heavy rain)", "このため似た選択圧（光をめぐる競争、大雨など）がかかる", "令它們面對相似的選擇壓力（如爭光、大雨）"), L("Unrelated species on different continents evolved similar adaptations independently (convergent evolution), so the communities look alike (e.g. buttress roots, drip tips, epiphytes)", "異なる大陸の類縁のない種が似た適応を独立に進化させた（収れん進化）ので群集が似て見える（板根、ドリップチップ、着生植物など）", "不同大陸上親緣疏遠的物種獨立演化出相似的適應特徵（趨同演化），因此群落外貌相似（如板根、滴水尖、附生植物）")],
      modelAnswer: L("All three regions have hot, very wet climates, which gives similar selection pressures such as competition for light. Unrelated species have evolved similar adaptations independently (convergent evolution), so the ecosystems look alike although the species differ.", "3地域はいずれも高温多雨の気候で、光をめぐる競争など似た選択圧がかかります。類縁のない種が似た適応を独立に進化させた（収れん進化）ため、種は異なっても生態系は似て見えます。", "三個地區都是炎熱多雨的氣候，帶來如爭光等相似的選擇壓力。親緣疏遠的物種獨立演化出相似的適應特徵（趨同演化），所以物種雖異，生態系統外貌卻相似。") },
    { id: "b4-1-q15", type: "short", ahl: false, difficulty: 2, ref: "B4.1.8", paper: "2", commandTerm: "Describe", marks: 4,
      stem: L("Describe adaptations of one named plant and one named animal to life in a hot desert.", "熱帯砂漠での生活に対する、名前のある植物1種と動物1種の適応を述べよ。", "描述一種有名稱的植物和一種有名稱的動物對熱帶沙漠生活的適應。"),
      markscheme: [L("Named plant, e.g. saguaro cactus (accept another valid desert plant)", "植物名（例: サワロサボテン。他の妥当な砂漠植物も可）", "植物名稱（如巨人柱仙人掌；其他有效的沙漠植物亦可）"), L("Plant adaptation with function, e.g. fleshy stem stores water / spines reduce water loss and deter herbivores / shallow wide roots absorb rain quickly", "植物の適応とその機能（例: 多肉質の茎が水をたくわえる／トゲが水分損失を減らし草食動物を防ぐ／浅く広い根が雨をすばやく吸収）", "植物的適應特徵及功能（如多肉莖儲水／刺減少失水並阻嚇草食動物／淺而闊的根迅速吸收雨水）"), L("Named animal, e.g. kangaroo rat or camel or fennec fox", "動物名（例: カンガルーネズミ、ラクダ、フェネック）", "動物名稱（如更格盧鼠、駱駝或大耳狐）"), L("Animal adaptation with function, e.g. nocturnal to avoid heat / concentrated urine reduces water loss / large ears lose heat", "動物の適応とその機能（例: 夜行性で暑さを避ける／濃い尿で水分損失を減らす／大きな耳で熱を逃がす）", "動物的適應特徵及功能（如夜間活動避熱／濃縮尿液減少失水／大耳散熱）")],
      modelAnswer: L("The saguaro cactus has a fleshy stem that stores water and leaves reduced to spines that cut water loss. The kangaroo rat is nocturnal, avoiding daytime heat, and produces very concentrated urine to save water.", "サワロサボテンは水をたくわえる多肉質の茎と、水分損失を減らすトゲ状の葉をもちます。カンガルーネズミは夜行性で日中の暑さを避け、非常に濃い尿で水を節約します。", "巨人柱仙人掌有儲水的多肉莖，葉退化成刺以減少失水。更格盧鼠夜間活動以避開日間炎熱，並排出極濃的尿液以節省水分。") },
    { id: "b4-1-q16", type: "short", ahl: false, difficulty: 3, ref: "B4.1.4", paper: "1B", commandTerm: "Evaluate", marks: 4,
      stem: L("A student ran a transect from the edge of a path into woodland. She concluded that low light intensity limits the distribution of a woodland plant. Evaluate this conclusion using the data (illustrative data).", "ある生徒が、小道の端から森林へトランセクトを行い、「弱い光が、ある森林植物の分布を制限している」と結論した。データを使ってこの結論を評価せよ（説明用データ）。", "一名學生沿由小徑邊緣進入林地的樣帶調查，並結論「低光強度限制了某林地植物的分佈」。利用數據評價此結論（示意數據）。"),
      data: L("<table><tr><th>Distance from path (m)</th><th>Light intensity (arbitrary units)</th><th>Soil pH</th><th>Plant cover (%)</th></tr><tr><td>0</td><td>95</td><td>6.8</td><td>60</td></tr><tr><td>5</td><td>70</td><td>6.5</td><td>45</td></tr><tr><td>10</td><td>45</td><td>6.0</td><td>25</td></tr><tr><td>15</td><td>25</td><td>5.6</td><td>10</td></tr><tr><td>20</td><td>10</td><td>5.2</td><td>2</td></tr></table>", "<table><tr><th>小道からの距離 (m)</th><th>光の強さ（任意単位）</th><th>土壌pH</th><th>植物の被度 (%)</th></tr><tr><td>0</td><td>95</td><td>6.8</td><td>60</td></tr><tr><td>5</td><td>70</td><td>6.5</td><td>45</td></tr><tr><td>10</td><td>45</td><td>6.0</td><td>25</td></tr><tr><td>15</td><td>25</td><td>5.6</td><td>10</td></tr><tr><td>20</td><td>10</td><td>5.2</td><td>2</td></tr></table>", "<table><tr><th>離小徑距離 (m)</th><th>光強度（任意單位）</th><th>土壤pH</th><th>植物覆蓋 (%)</th></tr><tr><td>0</td><td>95</td><td>6.8</td><td>60</td></tr><tr><td>5</td><td>70</td><td>6.5</td><td>45</td></tr><tr><td>10</td><td>45</td><td>6.0</td><td>25</td></tr><tr><td>15</td><td>25</td><td>5.6</td><td>10</td></tr><tr><td>20</td><td>10</td><td>5.2</td><td>2</td></tr></table>"),
      markscheme: [L("Supports: cover falls (60 % to 2 %) as light falls (95 to 10), a positive correlation (quote data)", "支持: 光が弱まる（95→10）につれ被度が減る（60 %→2 %）。正の相関（データを引用）", "支持：光強度下降（95至10），覆蓋下降（60 %至2 %），呈正相關（引用數據）"), L("Soil pH also falls with distance, so pH (or another variable) could be the limiting factor; the two variables are confounded", "土壌pHも距離とともに下がるので、pH（や他の変数）が制限要因かもしれない。2つの変数が交絡している", "土壤pH也隨距離下降，所以限制因素可能是pH（或其他變量）；兩個變量互相混雜"), L("Correlation does not prove cause; need experiments (e.g. grow plants at different light levels with pH controlled) or more transects", "相関は原因を証明しない。実験（pHを一定にして光の強さを変えて育てる）や追加のトランセクトが必要", "相關性不證明因果；需要實驗（如控制pH，在不同光強度下種植）或更多樣帶"), L("Limitations: one transect only, few points, no repeats (accept other valid limitations)", "限界: トランセクトが1本のみ、地点が少ない、繰り返しがない（他の妥当な限界も可）", "局限：只有一條樣帶、取樣點少、沒有重複（其他有效局限亦可）")],
      modelAnswer: L("The data support the conclusion because plant cover falls from 60 % to 2 % as light falls from 95 to 10. However, soil pH also falls along the transect, so pH may be the limiting factor, or both may contribute. A correlation does not prove cause, so the student needs an experiment that changes light while holding pH constant, and repeat transects.", "光が95から10に下がると被度が60 %から2 %に下がるので、データは結論を支持します。しかし土壌pHも同じように下がっており、制限要因がpHかもしれず、両方が関与するかもしれません。相関は原因を証明しないので、pHを一定にして光を変える実験と、トランセクトの繰り返しが必要です。", "光強度由95降至10時，覆蓋由60 %降至2 %，所以數據支持此結論。但土壤pH也沿樣帶下降，所以限制因素可能是pH，或兩者皆有影響。相關性不證明因果，因此需要在控制pH下改變光強度的實驗，並重複樣帶調查。") },
    { id: "b4-1-q17", type: "mcq", ahl: false, difficulty: 2, ref: "B4.1.3", paper: "1A", stem: L("A shrub can survive between -5 °C and 35 °C and grows best at about 20 °C. It is absent from a site with good soil and plenty of light, where the mean July temperature is 38 °C. What is the best explanation?", "ある低木は-5 °Cから35 °Cの間で生存でき、20 °C付近で最もよく育つ。土壌がよく光も十分だが7月の平均気温が38 °Cの地点には生えていない。最もよい説明はどれか。", "某灌木能在-5 °C至35 °C之間生存，約20 °C時生長最佳。在一個土壤良好、光照充足但7月平均氣溫為38 °C的地點卻沒有它。哪一項是最佳解釋？"), options: [L("January temperatures are below its optimum.", "1月の気温が最適温度より低い。", "一月氣溫低於其最適溫度。"), L("July temperature is above its upper limit of tolerance, so temperature is the limiting factor.", "7月の気温が耐性の上限を超えており、気温が制限要因になっている。", "七月氣溫高於其耐受上限，所以溫度是限制因素。"), L("Good soil and light make the species stop needing a range of tolerance.", "よい土壌と光があると、その種は耐性の範囲を必要としなくなる。", "良好的土壤和光線令該物種不再需要耐受範圍。"), L("The shrub is at its optimum temperature, so it is stressed by the heat.", "低木は最適温度にあるので、暑さでストレスを受けている。", "灌木正處於最適溫度，因此受熱而受壓。")], answer: 1, explanation: L("38 °C is above the shrub's upper limit of 35 °C, so it cannot survive there however good the other factors are. A is wrong because -5 °C is its lower limit and January must stay within the range. C is wrong because every species has a range of tolerance for each factor. D is wrong because 38 °C is not the optimum (about 20 °C).", "38 °Cは低木の上限35 °Cを超えているため、他の要因がどれほどよくても生存できません。Aは誤りで、-5 °Cが下限なので1月は範囲内に収まります。Cは誤りで、どの種にも各要因に対する耐性の範囲があります。Dは誤りで、38 °Cは最適（約20 °C）ではありません。", "38 °C高於灌木35 °C的上限，不論其他因素多好都不能生存。A錯，因為-5 °C才是下限，一月氣溫仍在範圍內。C錯，因為每個物種對每項因素都有耐受範圍。D錯，因為38 °C不是最適溫度（約20 °C）。") },
    { id: "b4-1-q18", type: "short", ahl: false, difficulty: 3, ref: "B4.1.4", paper: "1B", commandTerm: "Suggest", marks: 4, stem: L("A transect was run inland from the sea across a sand-dune system (illustrative data). Species X is a pioneer grass and species Y is a shrub. (a) Describe the distribution of Y (2 marks). (b) Suggest, with evidence, a limiting factor for Y near the sea (2 marks).", "砂丘地帯で、海から内陸へトランセクトを行った（説明用データ）。種Xは先駆的なイネ科植物、種Yは低木である。(a) Yの分布を述べよ（2点）。(b) 海に近い場所でYを制限する要因を、根拠とともに示唆せよ（2点）。", "沿海岸向內陸橫過沙丘系統進行樣帶調查（示意數據）。物種X是先驅禾草，物種Y是灌木。(a) 描述Y的分佈（2分）。(b) 憑證據提出在近海處限制Y的因素（2分）。"), data: L("<table><tr><th>Distance from sea (m)</th><th>Relative soil salt content (arbitrary units)</th><th>Cover of X (%)</th><th>Cover of Y (%)</th></tr><tr><td>0</td><td>9</td><td>5</td><td>0</td></tr><tr><td>10</td><td>7</td><td>40</td><td>0</td></tr><tr><td>20</td><td>4</td><td>55</td><td>5</td></tr><tr><td>30</td><td>2</td><td>30</td><td>35</td></tr><tr><td>40</td><td>1</td><td>10</td><td>60</td></tr><tr><td>50</td><td>1</td><td>2</td><td>75</td></tr></table>", "<table><tr><th>海からの距離 (m)</th><th>土壌の相対的な塩分（任意単位）</th><th>Xの被度 (%)</th><th>Yの被度 (%)</th></tr><tr><td>0</td><td>9</td><td>5</td><td>0</td></tr><tr><td>10</td><td>7</td><td>40</td><td>0</td></tr><tr><td>20</td><td>4</td><td>55</td><td>5</td></tr><tr><td>30</td><td>2</td><td>30</td><td>35</td></tr><tr><td>40</td><td>1</td><td>10</td><td>60</td></tr><tr><td>50</td><td>1</td><td>2</td><td>75</td></tr></table>", "<table><tr><th>與海岸距離 (m)</th><th>土壤相對鹽含量（任意單位）</th><th>X的覆蓋率 (%)</th><th>Y的覆蓋率 (%)</th></tr><tr><td>0</td><td>9</td><td>5</td><td>0</td></tr><tr><td>10</td><td>7</td><td>40</td><td>0</td></tr><tr><td>20</td><td>4</td><td>55</td><td>5</td></tr><tr><td>30</td><td>2</td><td>30</td><td>35</td></tr><tr><td>40</td><td>1</td><td>10</td><td>60</td></tr><tr><td>50</td><td>1</td><td>2</td><td>75</td></tr></table>"), markscheme: [L("(a) Y is absent from 0 and 10 m, then appears at 20 m (5 %)", "(a) Yは0 mと10 mにはなく、20 m（5 %）から現れる", "(a) Y在0 m和10 m缺席，至20 m才出現（5 %）"), L("(a) Cover then increases steadily with distance from the sea, to 75 % at 50 m (quote data)", "(a) その後、海から離れるにつれて被度が着実に増え、50 mで75 %になる（データを引用）", "(a) 其後覆蓋率隨與海岸距離增加而穩定上升，50 m時達75 %（引用數據）"), L("(b) Soil salt content is highest (9 and 7) where Y is absent: a negative correlation between salt and Y", "(b) Yがいない場所で土壌の塩分が最も高い（9と7）。塩分とYの間に負の相関がある", "(b) Y缺席處土壤鹽含量最高（9和7）：鹽與Y呈負相關"), L("(b) So high salinity (outside Y's range of tolerance) may be the limiting factor; other variables, such as wind or moving sand, could also contribute", "(b) したがって高い塩分（Yの耐性の範囲外）が制限要因かもしれない。風や動く砂など他の変数も関与しうる", "(b) 所以高鹽度（超出Y的耐受範圍）可能是限制因素；風或流動沙等其他變量也可能有影響")], modelAnswer: L("(a) Y is absent at 0 and 10 m and first appears at 20 m (5 %), then increases steadily to 75 % at 50 m. (b) Soil salt content is highest (9 and 7) where Y is absent and falls as Y increases, so high salinity may be beyond Y's range of tolerance and be the limiting factor. This is only a correlation, because other variables such as wind or moving sand also change along the transect.", "(a) Yは0 mと10 mにはなく、20 m（5 %）で初めて現れ、その後着実に増えて50 mで75 %になる。(b) Yがいない場所で土壌の塩分が最も高く（9と7）、Yが増えるにつれて塩分は下がる。よって高い塩分がYの耐性の範囲外で、制限要因かもしれない。ただし相関にすぎず、風や動く砂など他の変数もトランセクトに沿って変化している。", "(a) Y在0 m和10 m缺席，20 m（5 %）才首次出現，之後穩定上升至50 m的75 %。(b) Y缺席處土壤鹽含量最高（9和7），並隨Y增加而下降，所以高鹽度可能超出Y的耐受範圍，成為限制因素。但這只是相關，因為風或流動沙等其他變量也沿樣帶改變。") },
    { id: "b4-1-q19", type: "short", ahl: false, difficulty: 2, ref: "B4.1.6", paper: "1B", commandTerm: "Deduce", marks: 3, stem: L("Using the biome graph in section B4.1.6, deduce the most likely biome at each site (illustrative data): site P, 22 °C and 120 mm rainfall; site Q, 27 °C and 3200 mm rainfall; site R, -9 °C and 350 mm rainfall.", "B4.1.6のバイオーム図を使い、各地点で最も可能性の高いバイオームを推論せよ（説明用データ）。地点P: 22 °C、降水量120 mm。地点Q: 27 °C、降水量3200 mm。地点R: -9 °C、降水量350 mm。", "利用B4.1.6的生物群系圖，推斷各地點最可能的生物群系（示意數據）：地點P，22 °C，雨量120 mm；地點Q，27 °C，雨量3200 mm；地點R，-9 °C，雨量350 mm。"), markscheme: [L("P: hot desert (hot with very low rainfall)", "P: 砂漠（高温でごく少雨）", "P：熱帶沙漠（炎熱且雨量極低）"), L("Q: tropical forest (hot with very high rainfall)", "Q: 熱帯林（高温でごく多雨）", "Q：熱帶森林（炎熱且雨量極高）"), L("R: tundra (very cold with low rainfall)", "R: ツンドラ（非常に寒冷で少雨）", "R：苔原（極寒冷且雨量低）")], modelAnswer: L("P is hot desert because it is hot with very little rain. Q is tropical forest because it is hot and very wet. R is tundra because it is very cold with low rainfall.", "Pは高温でほとんど雨が降らないので砂漠。Qは高温で非常に多雨なので熱帯林。Rは非常に寒く降水量が少ないのでツンドラ。", "P是熱帶沙漠，因為炎熱而雨量極少。Q是熱帶森林，因為炎熱而極多雨。R是苔原，因為極寒冷而雨量低。") },
    { id: "b4-1-q20", type: "multi", ahl: false, difficulty: 2, ref: "B4.1.2", paper: "1A", stem: L("Select ALL the features that are adaptations of mangrove trees to waterlogged, salty mud.", "水浸しで塩分の多い泥に対するマングローブの木の適応を、すべて選べ。", "選出所有屬於紅樹對水浸及含鹽泥土的適應特徵。"), options: [L("Roots that grow above the mud and take in air", "泥の上に出て空気を取り入れる根", "長出泥面並吸取空氣的根"), L("Removing salt at the roots or secreting it from the leaves", "根で塩を取り除く、または葉から塩を分泌する", "在根部排除鹽分或由葉分泌鹽分"), L("Leaves that roll up with stomata on the inside", "気孔を内側にして巻く葉", "氣孔在內側而捲起的葉"), L("A single very deep taproot to reach underground water", "地下水に届く1本の非常に深い主根", "一條很深的主根以到達地下水")], answer: [0, 1], explanation: L("A and B address the two problems of mangrove mud: little oxygen and salt. C is a feature of marram grass in dry, windy dunes. D does not help, because the mud is already waterlogged and the problem there is oxygen and salt, not lack of water.", "AとBはマングローブの泥の2つの問題、酸素の少なさと塩分に対応します。Cは乾燥して風の強い砂丘にすむマラムグラスの特徴です。Dは役に立ちません。泥はすでに水浸しで、問題は水不足ではなく酸素の少なさと塩分だからです。", "A和B針對紅樹泥土的兩個問題：氧氣少和鹽分。C是乾燥多風沙丘上濱草的特徵。D沒有幫助，因為泥土已經水浸，問題是缺氧和鹽分，而不是缺水。") }
  ]
});
})();
